(window.TRENER_PACKS=window.TRENER_PACKS||{})["ovr-i-elektroliz"]={"id": "ovr-i-elektroliz", "subject": "Химия", "title": "ОВР, электронный баланс (№19, 29) и электролиз (№20) ЕГЭ-2027 с нуля до 100 баллов", "version": "25.11.2026", "konspekt": "ovr-i-elektroliz", "codes": ["1.12", "1.13"], "kod": {"p": [{"id": "p1", "t": "Степень окисления, шкала ролей и 4 типа ОВР", "x": "ОВР — реакция с изменением степени окисления хотя бы одного элемента. Окислитель принимает электроны (СО падает, процесс — восстановление), восстановитель отдаёт электроны (СО растёт, процесс — окисление). Высшая СО даёт только окислительные свойства, низшая — только восстановительные, промежуточная — двойственные.", "ref": "01.1"}, {"id": "p2", "t": "Элемент vs вещество и все форматы № 19 КИМ", "x": "В задании № 19 строго различай вопрос про конкретный элемент и про вещество целиком: вода H2O, HCl и NH3 могут быть окислителями за счёт H^{+1} и восстановителями за счёт O^{−2}, Cl^{−1}, N^{−3}. В органике гидрирование снижает СО углерода (органика — окислитель), а окисление альдегидов и HCOOH повышает СО углерода (органика — восстановитель).", "ref": "02.1"}, {"id": "p3", "t": "Электронный баланс и критерии 2/2 балла в № 29", "x": "Число электронов, отданных восстановителем, равно числу электронов, принятых окислителем. Для двухатомных молекул (Cl2, I2, O2) удобно удваивать полусхему; при двойном окислении (FeS2, Cu2S) складывают электроны обоих элементов в одной формульной единице; при диспропорционировании коэффициенты ставят справа налево.", "ref": "03.1"}, {"id": "p4", "t": "Среда раствора (pH), перманганат и хром", "x": "В кислой среде (H2SO4(разб.), KHSO4, NH4HSO4) KMnO4 обесцвечивается до Mn^{2+}, в воде даёт бурый осадок MnO2↓ + KOH, в щёлочи — зелёный K2MnO4. Хром(+6) восстанавливается до Cr^{3+} (кислота), Cr(OH)3↓ (вода) или [Cr(OH)4]^{−}/[Cr(OH)6]^{3−} (щёлочь), а обратное окисление Cr^{+3} → CrO4^{2−} идёт в щёлочи.", "ref": "04.1"}, {"id": "p5", "t": "Кислоты-окислители, нитриты, H2O2 и галогены", "x": "HNO3 любой концентрации и H2SO4(конц.) с металлами не выделяют H2 (окисляют N^{+5} и S^{+6}); холодные концентрированные кислоты пассивируют Fe, Al и Cr. Пероксид H2O2 как окислитель переходит в H2O/OH^{−} (без газа), а как восстановитель — в O2↑. Хлор и бром в холодной щёлочи дают гипогалогенит (KClO), в горячей — галогенат (KClO3).", "ref": "05.1"}, {"id": "p6", "t": "Восстановители, граница ОВР/РИО и алгоритм отбора № 29", "x": "На общем перечне № 29–30 пары Fe^{3+} с I^{−}/S^{2−}/SO3^{2−} и Cu^{2+} с I^{−} — это ОВР (№ 29), а совместный гидролиз Al^{3+}/Cr^{3+} с CO3^{2−}/S^{2−} и переход CrO4^{2−} ⇄ Cr2O7^{2−} — это не-ОВР (№ 30). Выбор пары всегда фильтруют по каждому слову условия: цвет, осадок, газ, число солей.", "ref": "06.1"}, {"id": "p7", "t": "Физика электролиза и электролиз расплавов", "x": "Электролиз — вынужденная ОВР под действием постоянного тока: на катоде (–) идёт восстановление катионов, на аноде (+) — окисление анионов. В расплаве воды нет, поэтому разряжаются сами ионы вещества: так получают активные металлы (Li–Al) и фтор F2.", "ref": "07.1"}, {"id": "p8", "t": "Правила катода и анода для водных растворов", "x": "На инертном катоде в водном растворе: Li–Al и NH4^{+} дают только H2; Mn–Pb — металл и H2; Cu–Au — только металл; H^{+} кислот — H2. На инертном аноде: Cl^{−}, Br^{−}, I^{−}, S^{2−} дают неметалл; F^{−}, оксоанионы и OH^{−} дают O2; карбоксилаты RCOO^{−} дают алкан R–R и CO2 (синтез Кольбе).", "ref": "08.1"}, {"id": "p9", "t": "Суммарные уравнения, pH у электродов и активный анод", "x": "Разложение воды на катоде даёт H2↑ и OH^{−} (растёт pH, накапливается щёлочь), на аноде — O2↑ и H^{+} (падает pH, накапливается кислота). После полного расходования соли начинается второй этап — электролиз воды. На растворимом (активном) аноде окисляется сам металл анода (Cu − 2e⁻ → Cu^{2+}).", "ref": "09.1"}, {"id": "p10", "t": "Промышленное получение веществ и форматы № 20 КИМ", "x": "Активные металлы (Li–Mg) и F2 получают только электролизом расплавов солей/щелочей; алюминий Al — электролизом раствора Al2O3 в расплаве криолита Na3AlF6 (не AlCl3!). Хлор Cl2, H2, NaOH, Cu, Ag и O2 получают электролизом водных растворов соответствующих солей.", "ref": "10.1"}], "z": [{"id": "z1", "x": "Стандарт ФИПИ: степень окисления пишется знаком вперёд (Mn^{+7}, Fe^{+3}, S^{−2}), заряд иона — цифрой вперёд (Mn^{2+}, Fe^{3+}, SO4^{2−}), электрон — строго e⁻ (никогда ē).", "sk": "ox_state", "ref": "01.8"}, {"id": "z2", "x": "Исключения СО: в пероксидах O^{−1}, в OF2 — O^{+2}; в гидридах металлов H^{−1}; в пирите FeS2 — Fe^{+2} и S^{−1}; в NH4NO3 считают раздельно N^{−3} и N^{+5}.", "sk": "ox_state", "ref": "01.7"}, {"id": "z3", "x": "Двойное окисление (например, 4FeS2 + 11O2 → 2Fe2O3 + 8SO2) — НЕ диспропорционирование: электроны отдают два разных элемента (Fe и S), а принимает третий (O2).", "sk": "kim19_traps", "ref": "02.10"}, {"id": "z4", "x": "В № 29 окислитель и восстановитель всегда называют строго из левой части уравнения (исходные реагенты), а дробные коэффициенты и два уравнения «на выбор» не засчитываются.", "sk": "balance_fipi", "ref": "03.15"}, {"id": "z5", "x": "HCl (восстановитель) и HNO3 (окислитель) запрещено брать как инертную кислую среду для KMnO4 и K2Cr2O7. Инертная кислая среда — H2SO4(разб.), KHSO4, NaHSO4, NH4HSO4.", "sk": "ph_mn_cr", "ref": "04.4"}, {"id": "z6", "x": "Переход K2Cr2O7 + 2KOH → 2K2CrO4 + H2O (и обратный с H2SO4) — НЕ ОВР (везде Cr^{+6}). В Демо-2027 среда NH4HSO4 даёт третью соль (NH4)2SO4 и нарушает фильтр «раствор двух солей».", "sk": "ph_mn_cr", "ref": "04.11"}, {"id": "z7", "x": "Холодные HNO3(конц.) и H2SO4(конц.) пассивируют Fe, Al и Cr; при нагревании железо окисляется до +3. С H2SO4(конц.): NaCl даёт обмен (HCl↑), NaBr — Br2 + SO2↑, NaI — I2 + H2S↑.", "sk": "acids_h2o2_hal", "ref": "05.6"}, {"id": "z8", "x": "Fe^{3+} в растворе окисляет I^{−}, S^{2−}, SO3^{2−} (ОВР № 29), а Al^{3+}/Cr^{3+} с CO3^{2−}/S^{2−} — совместный гидролиз (РИО № 30). Обесцвечивание KMnO4 без осадка и газа дают Na2SO3 и KNO2, но не FeSO4 (жёлтый раствор).", "sk": "reducers_nav29", "ref": "06.7"}, {"id": "z9", "x": "Алюминий получают электролизом раствора Al2O3 в расплаве криолита Na3AlF6 (~950 °C), а НЕ из расплава AlCl3 (молекулярная решётка, возгоняется, не проводит ток).", "sk": "melt_electrolysis", "ref": "07.12"}, {"id": "z10", "x": "В расплаве гидрида NaH водород имеет СО −1 (H^{−}) и окисляется на АНОДЕ (+) до H2↑; в расплаве щёлочи NaOH на аноде выделяются O2↑ и H2O↑.", "sk": "melt_electrolysis", "ref": "07.10"}, {"id": "z11", "x": "Фториды в водном растворе (NaF, KF, CuF2, HF) на аноде ВСЕГДА дают кислород O2↑ (из воды), а не фтор F2. Фтор получают только из расплава.", "sk": "solution_rules", "ref": "08.12"}, {"id": "z12", "x": "Металлы средней активности (Mn–Pb, включая Fe, Zn, Cr, Sn, Pb) в № 20 на катоде всегда дают «металл и водород»; Pb стоит ДО (H2), а Cu, Hg, Ag — ПОСЛЕ (H2).", "sk": "solution_rules", "ref": "08.12"}, {"id": "z13", "x": "Водные растворы Na2SO4, KNO3, NaF, NaOH, H2SO4, KHSO4 сводятся к электролизу воды (2H2O → 2H2↑ + O2↑), а ацетат CH3COONa на аноде даёт этан C2H6↑ и CO2↑ (синтез Кольбе).", "sk": "summary_electrolysis", "ref": "09.5"}, {"id": "z14", "x": "Для получения Cl2, H2 и NaOH в промышленности ведут электролиз водного раствора NaCl; электролиз расплава NaCl даёт только Na и Cl2 (без H2 и NaOH).", "sk": "kim20_industry", "ref": "10.5"}]}, "skills": [{"id": "ox_state", "name": "Степень окисления, шкала ролей и 4 типа ОВР", "ref": "01", "idea": "Безошибочно вычислять степени окисления в сложных неорганических и органических частицах, соблюдать стандарт записи ФИПИ и определять тип ОВР.", "pre": {"type": "one", "q": "Чему равна степень окисления серы в пирите FeS2 и кислорода в фториде кислорода OF2 соответственно?", "o": ["−1 и +2", "−2 и −2", "−1 и −1", "+2 и +2"], "a": 0, "ex": "Пирит FeS2 содержит дисульфид-ион S2^{2−} (Fe^{+2}, у каждого атома серы S^{−1}). В OF2 фтор более электроотрицателен (F^{−1}), поэтому у кислорода СО равна +2.", "d": {"1": "Если поставить S^{−2}, у железа вышла бы невозможная СО +4; а в OF2 фтор сильнее кислорода, поэтому у O положительная СО.", "2": "O^{−1} бывает в пероксидах (H2O2, Na2O2), но не во фториде OF2.", "3": "Сера более электроотрицательна, чем железо, поэтому в пирите её СО отрицательна (−1)."}}, "pair": {"type": "one", "cases": [["Уксусная кислота CH3COOH", "Два атома углерода с разным окружением: группа −CH3 и группа −COOH"], ["Нитрат аммония NH4NO3", "Два атома азота в разных ионах: катион NH4^{+} и анион NO3^{−}"]], "q": "Как правильно определить степени окисления углерода в CH3COOH и азота в NH4NO3?", "o": ["В CH3COOH раздельно C^{−3} (в −CH3) и C^{+3} (в −COOH); в NH4NO3 раздельно N^{−3} (в NH4^{+}) и N^{+5} (в NO3^{−})", "Посчитать среднюю СО по брутто-формуле: C^{0} в CH3COOH и N^{+1} в NH4NO3", "Оба углерода в CH3COOH имеют СО +4, а оба азота в NH4NO3 имеют СО +5", "В CH3COOH C^{−4} и C^{+4}, а в NH4NO3 оба атома азота имеют СО −3"], "a": 0, "ex": "Степень окисления считают для каждого атома с учётом его связей или иона: в −CH3 три связи C–H дают C^{−3}, в −COOH три связи с O дают C^{+3}; в NH4^{+} азот −3, в NO3^{−} азот +5."}, "fade": {"q": "Классифицируй реакцию 2H2S + SO2 → 3S↓ + 2H2O и определи роли реагентов:", "steps": ["В сероводороде H2S сера имеет СО {−2|+2|0} (минимальная СО → только {восстановитель|окислитель|среда}).", "В сернистом газе SO2 сера имеет СО {+4|+6|−2}, а в продукте S она равна {0|−2|+4}, значит SO2 здесь — {окислитель|восстановитель|катализатор}.", "Поскольку атомы одного элемента из двух разных СО сходятся в одну промежуточную, это реакция {сопропорционирования|диспропорционирования|внутримолекулярная}."]}, "bug": {"q": "Найди ошибочный шаг в оформлении и анализе ОВР для ЕГЭ-2027:", "steps": ["В гидриде кальция CaH2 кальций имеет СО +2, а водород — СО −1.", "В реакции 2KClO3 —t°, MnO2→ 2KCl + 3O2↑ хлор и кислород меняют СО внутри одной молекулы — это внутримолекулярная ОВР.", "В электронном балансе степень окисления марганца следует записывать как Mn^{7+}, а электрон — символом ē.", "Элемент в промежуточной степени окисления (например, S^{+4} в Na2SO3) может проявлять как окислительные, так и восстановительные свойства."], "bad": 2, "fix": "Степень окисления в ЕГЭ пишется знаком перед цифрой (Mn^{+7}), а электрон — строго e⁻ (никогда ē). Формат цифрой вперёд (Mn^{2+}) используется только для заряда иона.", "why": "Путаница между степенью окисления и зарядом иона, а также нестандартный символ ē приводят к снижению балла в части 2."}, "recall": {"q": "Назови по памяти 4 исключения при расчёте СО и 4 структурных типа ОВР с примерами.", "points": ["Кислород: O^{−1} в пероксидах (H2O2, Na2O2), O^{+2} в OF2.", "Водород: H^{−1} в гидридах металлов (NaH, CaH2).", "Сложные частицы: FeS2 (Fe^{+2}, S^{−1}), NH4NO3 (N^{−3} и N^{+5}), CH3COOH (C^{−3} и C^{+3}).", "Четыре типа: межмолекулярная (Zn + HCl), внутримолекулярная (разложение KClO3), диспропорционирование (Cl2 + KOH), сопропорционирование (H2S + SO2)."]}}, {"id": "kim19_traps", "name": "Все форматы и «хамелеоны» задания № 19 КИМ", "ref": "02", "idea": "Отличать роль конкретного элемента от роли вещества целиком (H2O, HCl, NH3, H2O2), анализировать органические ОВР и мгновенно отсекать не-ОВР двойники.", "pre": {"type": "one", "q": "В какой реакции вода H2O выступает в роли ВОССТАНОВИТЕЛЯ?", "o": ["2F2 + 2H2O → 4HF + O2↑", "2Na + 2H2O → 2NaOH + H2↑", "2KMnO4 + 3Na2SO3 + H2O → 2MnO2↓ + 3Na2SO4 + 2KOH", "CaO + H2O → Ca(OH)2"], "a": 0, "ex": "Вода — восстановитель только за счёт кислорода O^{−2} → O2^{0} под действием фтора F2 (самого сильного окислителя).", "d": {"1": "С натрием вода окислитель за счёт H^{+1} → H2^{0}.", "2": "Здесь вода лишь среда — степени окисления H и O в ней не меняются.", "3": "Реакция соединения оксида с водой — вообще не ОВР."}}, "pair": {"type": "one", "cases": [["Гидрирование этилена: CH2=CH2 + H2 → CH3–CH3", "Углерод меняет СО с −2 до −3, водород с 0 до +1"], ["Окисление этаналя: CH3CHO + 2[Ag(NH3)2]OH → CH3COONH4 + 2Ag↓ + 3NH3↑ + H2O", "Карбонильный углерод меняет СО с +1 до +3"]], "q": "Какую роль играет органическое вещество в первой и второй реакциях соответственно?", "o": ["В первой — окислитель, во второй — восстановитель", "В обеих реакциях — восстановитель", "В первой — восстановитель, во второй — окислитель", "Первая реакция не является ОВР, во второй — восстановитель"], "a": 0, "ex": "При гидрировании углерод принимает электроны (−2 → −3), значит алкен — окислитель (а H2 — восстановитель). При окислении альдегида углерод отдаёт электроны (+1 → +3), значит альдегид — восстановитель."}, "fade": {"q": "Определи свойство азота в каждой из трёх реакций прототипа № 19:", "steps": ["В разложении NH4NO3 → N2O↑ + 2H2O азот из −3 и +5 переходит в +1, значит азот здесь {и окислитель, и восстановитель|только окислитель|не проявляет ОВ-свойств}.", "В реакции 2NO2 + 2NaOH → NaNO2 + NaNO3 + H2O азот из +4 переходит в +3 и +5, значит он {и окислитель, и восстановитель|только восстановитель|только окислитель}.", "В реакции NH4Cl + NaOH → NaCl + NH3↑ + H2O степень окисления азота остаётся {−3|+3|+5}, поэтому азот {не проявляет ОВ-свойств|только восстановитель|и окислитель, и восстановитель}."]}, "bug": {"q": "Найди ошибочное утверждение в разборе ловушек задания № 19:", "steps": ["В реакции Cu + 4HNO3(конц.) → Cu(NO3)2 + 2NO2↑ + 2H2O азот проявляет роль только окислителя, хотя часть нитрат-ионов не меняет СО.", "В реакции 4FeS2 + 11O2 → 2Fe2O3 + 8SO2↑ происходит диспропорционирование пирита.", "Реакция 2K2CrO4 + H2SO4 → K2Cr2O7 + K2SO4 + H2O не является окислительно-восстановительной.", "В реакции Fe + 2HCl → FeCl2 + H2↑ соляная кислота HCl выступает окислителем за счёт атомов H^{+1}."], "bad": 1, "fix": "Обжиг пирита FeS2 + O2 — это двойное окисление (межмолекулярная ОВР), а не диспропорционирование: и железо (+2 → +3), и сера (−1 → +4) здесь восстановители, а кислород O2 — окислитель.", "why": "При диспропорционировании один и тот же элемент одновременно повышает и понижает СО; в пирите оба элемента только повышают СО."}, "recall": {"q": "Назови по памяти 4 «хамелеона» задания № 19 (вещества с разной ролью) и 3 классических не-ОВР двойника.", "points": ["H2O: окислитель за счёт H^{+1} (с Na), восстановитель за счёт O^{−2} (с F2), среда (в KMnO4 + Na2SO3 + H2O).", "HCl: окислитель за счёт H^{+1} (с Fe), восстановитель за счёт Cl^{−1} (с KMnO4/MnO2), не-ОВР (с NaOH).", "NH3: восстановитель за счёт N^{−3} (с O2, CuO), окислитель за счёт H^{+1} (с Na при t°), не-ОВР (с HCl).", "H2O2: окислитель (O^{−1} → O^{−2}), восстановитель (O^{−1} → O2^{0}), диспропорционирование (2H2O2 → 2H2O + O2).", "Не-ОВР двойники: переход CrO4^{2−} ⇄ Cr2O7^{2−}, гидролиз/обмен, разложение карбонатов и Cu(OH)2, гидратация алкенов."]}}, {"id": "balance_fipi", "name": "Метод электронного баланса, двойное окисление и критерии ФИПИ", "ref": "03", "idea": "Составлять баланс с удвоением двухатомных молекул, двойным окислением и диспропорционированием, оформляя № 29 строго на 2/2 балла.", "pre": {"type": "one", "q": "Сколько электронов отдаёт одна формульная единица пирита FeS2 при обжиге до Fe2O3 и SO2?", "o": ["11", "15", "7", "5"], "a": 0, "ex": "В FeS2 железо переходит из +2 в +3 (−1e⁻), а два атома серы из 2S^{−1} в 2S^{+4} (−10e⁻). Сумма на 1 FeS2: 1 + 10 = 11 электронов.", "d": {"1": "15 электронов отдаётся при окислении до H2SO4 (+6) концентрированной азотной кислотой, а при обжиге образуется SO2 (+4).", "2": "7 электронов получилось бы при ошибке в учёте индекса 2 у серы или неверной СО.", "3": "5 электронов отдаёт один атом S^{−1} до S^{+4}, но в пирите два атома серы и ещё окисляется Fe^{+2}."}}, "pair": {"type": "one", "cases": [["Работа А", "Верно выбраны вещества под условие, верно уравнено уравнение, но перепутаны названия окислителя и восстановителя"], ["Работа Б", "Записано два разных уравнения ОВР «на выбор» или уравнение не удовлетворяет признаку условия, но баланс к нему идеальный"]], "q": "Какие баллы поставят эксперты ФИПИ за работу А и работу Б в задании № 29?", "o": ["Работа А — 1 балл, работа Б — 0 баллов", "Работа А — 1 балл, работа Б — 1 балл", "Работа А — 2 балла, работа Б — 0 баллов", "Обе работы — 0 баллов"], "a": 0, "ex": "За верное уравнение, соответствующее условию, при ошибке в балансе/ролях ставят 1 балл (работа А). Но если уравнение не отвечает условию или дано несколько уравнений на выбор, ставится 0 баллов (работа Б)."}, "fade": {"q": "Собери электронный баланс реакции 3Cl2 + 6KOH(гор.) —t°→ 5KCl + KClO3 + 3H2O:", "steps": ["Восстановление хлора: Cl^{0} + {1e⁻|2e⁻|5e⁻} → Cl^{−1} | множитель {5|1|3}.", "Окисление хлора: Cl^{0} − {5e⁻|1e⁻|3e⁻} → Cl^{+5} | множитель {1|5|3}.", "При диспропорционировании множители сначала ставят в {правую часть|левую часть|перед KOH}, получая 5KCl + 1KClO3, откуда слева получается {3Cl2|6Cl2|2Cl2}."]}, "bug": {"q": "Найди ошибку в оформлении задания № 29 для реакции 2KMnO4 + 16HCl(конц.) → 2KCl + 2MnCl2 + 5Cl2↑ + 8H2O:", "steps": ["Mn^{+7} + 5e⁻ → Mn^{+2} | множитель 2 (восстановление).", "2Cl^{−1} − 2e⁻ → Cl2^{0} | множитель 5 (окисление).", "Проверка по кислороду: слева в 2KMnO4 ровно 8 атомов O, справа в 8H2O ровно 8 атомов O.", "Окислитель — MnCl2 (за счёт Mn^{+2}), восстановитель — Cl2 (за счёт Cl^{0})."], "bad": 3, "fix": "Окислитель и восстановитель всегда называют строго по исходным реагентам: KMnO4 (за счёт Mn^{+7}) — окислитель, HCl (за счёт Cl^{−1}) — восстановитель.", "why": "Продукты реакции (MnCl2 и Cl2) уже завершили перенос электронов; указание продуктов вместо реагентов лишает балла за второй элемент ответа."}, "recall": {"q": "Назови по памяти 5 шагов алгоритма электронного баланса и золотой стандарт записи окислителя и восстановителя.", "points": ["1) Расставить СО и выписать изменившиеся элементы; 2) Учесть индексы двухатомных молекул (2Cl^{−1} → Cl2^{0}) или двойного окисления; 3) Найти НОК и наименьшие целые множители; 4) Перенести множители и уравнять металлы, среду и водород; 5) Проверить кислород слева и справа.", "Золотой стандарт ролей: писать полную формулу исходного реагента и уточнять элемент в скобках, например: KMnO4 (за счёт Mn^{+7}) — окислитель."]}}, {"id": "ph_mn_cr", "name": "Среда (pH), перманганат, хром и эталон Демо-2027", "ref": "04", "idea": "Выбирать корректную среду (включая KHSO4 и NH4HSO4), управлять продуктами KMnO4 и Cr^{+6}/Cr^{+3} и считать число солей в Демо-2027.", "pre": {"type": "one", "q": "В перечне Демоверсии ЕГЭ-2027 даны: KNO2, K2SO3, K2Cr2O7, H2SO4, KI, NH4HSO4. Требуется образование простого вещества и раствора ДВУХ солей. Почему нельзя взять среду NH4HSO4?", "o": ["С NH4HSO4 в растворе образуются ТРИ соли: Cr2(SO4)3, K2SO4 и (NH4)2SO4", "NH4HSO4 не создаёт кислую среду в водном растворе", "NH4HSO4 окислит иодид калия до иода быстрее дихромата", "В присутствии NH4HSO4 выпадет осадок Cr(OH)3↓"], "a": 0, "ex": "Гидросульфат аммония создаёт кислую среду, но вносит лишний катион NH4^{+}, из-за чего в продуктах окажутся три соли (Cr2(SO4)3, K2SO4, (NH4)2SO4), что нарушает условие «раствора двух солей».", "d": {"1": "Гидросульфаты (KHSO4, NH4HSO4) отлично создают кислую среду — причина отказа именно в числе солей.", "2": "NH4HSO4 не окисляет иодид-ион.", "3": "В кислой среде образуется растворимая соль Cr2(SO4)3, а не осадок гидроксида."}}, "pair": {"type": "one", "cases": [["2KMnO4 + 5Na2SO3 + 3H2SO4(разб.)", "Раствор обесцвечивается, Mn^{+7} → Mn^{+2} (+5e⁻)"], ["2KMnO4 + 3Na2SO3 + H2O", "Выпадает бурый осадок MnO2↓, Mn^{+7} → Mn^{+4} (+3e⁻), образуется KOH"]], "q": "А что произойдёт, если провести реакцию KMnO4 с Na2SO3 в щелочной среде (KOH)?", "o": ["Малиновый раствор станет изумрудно-зелёным без осадка за счёт образования манганата K2MnO4 (Mn^{+7} → Mn^{+6}, +1e⁻)", "Выпадет белый осадок Mn(OH)2 и выделится газ SO2↑", "Раствор обесцветится до MnSO4 без выпадения осадка", "Реакция не пойдёт, так как KMnO4 не реагирует в щелочной среде"], "a": 0, "ex": "В избытке щёлочи перманганат принимает только 1e⁻ и переходит в зелёный раствор манганата: 2KMnO4 + Na2SO3 + 2KOH → 2K2MnO4 + Na2SO4 + H2O."}, "fade": {"q": "Проследи переходы соединений хрома при изменении pH и в ОВР:", "steps": ["Добавление KOH к оранжевому K2Cr2O7 даёт жёлтый {K2CrO4|K3[Cr(OH)6]|Cr(OH)3}, и эта реакция {не является ОВР|является восстановлением|является диспропорционированием}.", "При восстановлении Cr^{+6} в нейтральной среде (H2O) выпадает серо-зелёный осадок {Cr(OH)3|Cr2O3|Cr2(SO4)3}, а в избытке KOH образуется растворимый комплекс {K[Cr(OH)4] / K3[Cr(OH)6]|K2Cr2O7|Cr(OH)3}.", "Обратное окисление Cr^{+3} до жёлтого хромата CrO4^{2−} пероксидом водорода в растворе проводят в {щелочной|кислой|нейтральной} среде."]}, "bug": {"q": "Найди химическую ошибку в рассуждениях про среды и марганец:", "steps": ["Соляную кислоту HCl нельзя использовать как инертную кислую среду для KMnO4, так как Cl^{−} окисляется до Cl2↑.", "В реакции 2KMnO4 + 5K2SO3 + 6KHSO4 → 2MnSO4 + 9K2SO4 + 3H2O гидросульфат калия KHSO4 выступает кислой средой.", "В нейтральной среде при действии SO2 на KMnO4 (2KMnO4 + 5SO2 + 2H2O) в продуктах образуются MnO2↓ и щёлочь KOH.", "Зелёный манганат K2MnO4 устойчив в щёлочи, но при подкислении диспропорционирует на KMnO4 и MnO2↓."], "bad": 2, "fix": "Если восстановитель — кислотный оксид/кислота (SO2), то щёлочь справа несовместима с ним и образуется кислая среда: 2KMnO4 + 5SO2 + 2H2O → 2MnSO4 + K2SO4 + 2H2SO4.", "why": "В нейтральной среде с солями (Na2SO3) образуются MnO2↓ + KOH, но с кислотным SO2 образуется серная кислота, которая переводит марганец в MnSO4."}, "recall": {"q": "Назови по памяти продукты восстановления KMnO4 и K2Cr2O7 в трёх средах (H^{+}, H2O, OH^{−}) и их цвета.", "points": ["KMnO4: H^{+} → Mn^{2+} (бесцветный); H2O → MnO2↓ (бурый осадок + KOH); OH^{−} → K2MnO4 (изумрудно-зелёный раствор).", "Cr^{+6}: H^{+} → Cr^{3+} (зелёный/фиолетово-зелёный раствор); H2O → Cr(OH)3↓ (серо-зелёный осадок); OH^{−} → K[Cr(OH)4] / K3[Cr(OH)6] (изумрудно-зелёный раствор)."]}}, {"id": "acids_h2o2_hal", "name": "Кислоты-окислители, нитриты, H2O2 и галогены", "ref": "05", "idea": "Предсказывать продукты HNO3 и H2SO4(конц.) с учётом пассивации, двойственность KNO2 и H2O2, ряд активности галогенов и их реакции со щёлочью.", "pre": {"type": "one", "q": "В какие реакции вступают твёрдые NaCl, NaBr и NaI с концентрированной серной кислотой H2SO4(конц.) при нагревании?", "o": ["NaCl — обмен (HCl↑, не ОВР); NaBr — ОВР (Br2 + SO2↑); NaI — ОВР (I2 + H2S↑)", "Все три соли вступают в ОВР с выделением Cl2, Br2, I2 и SO2↑", "Все три соли дают только реакции обмена с выделением HCl, HBr, HI", "NaCl и NaBr дают обмен, а NaI даёт O2↑ и I2"], "a": 0, "ex": "Восстановительная сила галогенидов растёт вниз по группе: Cl^{−} не окисляется H2SO4(конц.) (только обмен до HCl↑), Br^{−} восстанавливает S^{+6} до SO2↑, а сильнейший восстановитель I^{−} — до H2S↑.", "d": {"1": "Хлорид-ион слишком слабый восстановитель для H2SO4(конц.), Cl2 не образуется.", "2": "HBr и HI окисляются концентрированной серной кислотой прямо в момент выделения.", "3": "Бромид окисляется H2SO4(конц.) до Br2 + SO2↑, а иодид восстанавливает серу до H2S↑."}}, "pair": {"type": "one", "cases": [["2KMnO4 + 5H2O2 + 3H2SO4(разб.)", "Выделяется газ O2↑, раствор обесцвечивается"], ["2KI + H2O2 + H2SO4(разб.)", "Выпадает I2↓, газ НЕ выделяется"]], "q": "Почему в первой реакции пероксид водорода даёт газ O2↑, а во второй газ не выделяется?", "o": ["С сильным окислителем KMnO4 пероксид — восстановитель (O^{−1} → O2^{0}↑), а с восстановителем KI — окислитель (O^{−1} → O^{−2} в H2O)", "Во второй реакции кислород O2 полностью растворяется в KI", "В первой реакции H2O2 — окислитель, во второй — восстановитель", "Кислород выделяется только при разложении KMnO4, а H2O2 — катализатор"], "a": 0, "ex": "Двойственность H2O2: встречая более сильный окислитель (KMnO4, K2Cr2O7, Cl2, Ag2O), он отдаёт электроны с выделением O2↑; встречая восстановитель (KI, Na2SO3, FeSO4, K3[Cr(OH)6]), он принимает электроны, переходя в H2O/OH^{−} без газа."}, "fade": {"q": "Определи продукты реакций меди и цинка с азотной кислотой и нитратом:", "steps": ["С концентрированной HNO3 медь даёт бурый газ {NO2|NO|H2}, а с разбавленной HNO3 — бесцветный газ {NO|NO2|NH3}.", "Железо, алюминий и хром на холоде в концентрированных HNO3 и H2SO4 {пассивируются|выделяют H2|дают соли +2}, а при нагревании железо переходит в степень окисления {+3|+2|+6}.", "При нагревании цинка с нитратом натрия в избытке щёлочи (4Zn + NaNO3 + 7NaOH + 6H2O) образуются Na2[Zn(OH)4] и газ {NH3|NO2|H2}."]}, "bug": {"q": "Найди ошибку в правилах для галогенов и нитритов:", "steps": ["Окислительная сила галогенов убывает сверху вниз: F2 > Cl2 > Br2 > I2, поэтому Cl2 вытесняет Br2 из KBr, а Br2 вытесняет I2 из KI.", "В холодной щёлочи хлор диспропорционирует до KCl и KClO, а в горячей щёлочи — до KCl и KClO3.", "Фтор F2 вытесняет хлор Cl2 из водного раствора NaCl по реакции F2 + 2NaCl → 2NaF + Cl2↑.", "Нитрит калия KNO2 с KMnO4 в H2SO4 окисляется до KNO3 (без газа), а с KI в H2SO4 восстанавливается до газа NO↑."], "bad": 2, "fix": "Фтор F2 настолько активен, что в водном растворе мгновенно окисляет саму воду (2F2 + 2H2O → 4HF + O2↑), поэтому вытеснение галогенов из водных растворов солей работает только для Cl2 и Br2.", "why": "Классическая ловушка VIIA группы: ряд вытеснения в водном растворе начинается с хлора, но не со фтора."}, "recall": {"q": "Назови по памяти, как ведут себя KNO2, H2O2 и Cl2 в противоположных условиях.", "points": ["KNO2: с сильными ОК → KNO3 (без газа); с сильными ВС в кислоте (KI, H2S, FeSO4) → газ NO↑.", "H2O2: как ОК → H2O/OH^{−} (без газа); как ВС → газ O2↑.", "Cl2 + KOH: на холоде → KCl + KClO + H2O; при нагревании → 5KCl + KClO3 + 3H2O."]}}, {"id": "reducers_nav29", "name": "Восстановители, граница ОВР/РИО и навигатор № 29", "ref": "06", "idea": "Разводить ОВР № 29 и совместный гидролиз № 30 по таблице растворимости, расшифровывать качественные признаки и безошибочно отбирать пару из перечня 6 веществ.", "pre": {"type": "one", "q": "В перечне даны: KMnO4, Na2SO3, KI, H2SO4, Ba(OH)2, FeSO4. Требуется «обесцвечивание раствора без образования осадка и выделения газа». Какой восстановитель нужно выбрать?", "o": ["Na2SO3", "KI", "FeSO4", "Ba(OH)2"], "a": 0, "ex": "Для обесцвечивания KMnO4 нужна кислая среда H2SO4(разб.). KI даст бурый осадок I2↓, FeSO4 даст жёлто-бурый раствор Fe2(SO4)3 (раствор не обесцветится!), и только Na2SO3 даст бесцветный раствор MnSO4, Na2SO4 и K2SO4 без осадка и газа.", "d": {"1": "KI окисляется до I2↓ (осадок/бурое окрашивание — нарушает условие).", "2": "FeSO4 окисляется до Fe2(SO4)3, который окрашивает раствор в жёлто-бурый цвет, поэтому обесцвечивания нет.", "3": "Ba(OH)2 — щелочная среда (даст зелёный K2MnO4 и осадок BaSO4), а не восстановитель."}}, "pair": {"type": "one", "cases": [["2FeCl3 + 2KI → 2FeCl2 + I2↓ + 2KCl", "Прочерк в таблице растворимости ФИПИ на пересечении Fe^{3+} и I^{−}"], ["2AlCl3 + 3Na2CO3 + 3H2O → 2Al(OH)3↓ + 3CO2↑ + 6NaCl", "Прочерк в таблице растворимости ФИПИ на пересечении Al^{3+} и CO3^{2−}"]], "q": "Какое принципиальное отличие между этими двумя реакциями при распределении заданий № 29 и № 30?", "o": ["Первая — ОВР (подходит для № 29), вторая — совместный гидролиз без смены СО (только для № 30)", "Обе реакции являются ОВР и подходят для задания № 29", "Обе реакции являются реакциями ионного обмена (для № 30)", "Первая — РИО, вторая — ОВР с выделением CO2"], "a": 0, "ex": "Прочерки на пересечении Fe^{3+} с I^{−}/S^{2−}/SO3^{2−} и Cu^{2+} с I^{−} означают ОВР (№ 29), а прочерки Al^{3+}/Cr^{3+} с CO3^{2−}/S^{2−}/SO3^{2−} и Fe^{3+} с CO3^{2−} — совместный гидролиз без смены СО (№ 30)."}, "fade": {"q": "Расшифруй 3 качественных признака из условий задания № 29:", "steps": ["Признак «без видимых признаков» (бесцветные реагенты → бесцветные растворимые продукты без газа) даёт пара {H2O2 + Na2SO3|KMnO4 + Na2SO3 + H2SO4|FeCl3 + KI}.", "Признак «выпадение белого осадка и образование простого вещества без третьей среды» даёт пара {CuSO4 + KI|FeCl3 + KI|FeCl3 + H2S} (выпадают белый {CuI|CuI2|Cu2O} и I2).", "Признак «образование двух кислот» даёт реакция {SO2 + Cl2 + 2H2O|K2Cr2O7 + KI + H2SO4|Cu + HNO3(конц.)}."]}, "bug": {"q": "Найди ошибку в правилах отбора реакции из общего перечня № 29–30:", "steps": ["Вещества, использованные в задании № 29, разрешается повторно использовать в задании № 30.", "В реакции 2FeCl3 + Na2SO3 + H2O → 2FeCl2 + Na2SO4 + 2HCl железо(+3) восстанавливается до железа(+2), а сульфит окисляется до сульфата.", "Если в перечне есть FeCl3 и Na2CO3, их реакцию с выделением CO2↑ и выпадением Fe(OH)3↓ можно записать в задание № 29.", "В продуктах реакции № 29 нельзя одновременно писать несовместимые вещества (например, NH3 и HCl или кислоту и щёлочь)."], "bad": 2, "fix": "Реакция FeCl3 + Na2CO3 + H2O — это совместный гидролиз без изменения степеней окисления (везде Fe^{+3} и C^{+4}), она относится к № 30 и даст 0 баллов в № 29.", "why": "Перед записью в № 29 обязательно убедись, что хотя бы два элемента реально изменили степень окисления."}, "recall": {"q": "Назови по памяти 4 пары «прочерк в таблице растворимости → ОВР» и 4 пары «признак № 29 → эталонная реакция».", "points": ["ОВР-прочерки: Fe^{3+} + I^{−} (Fe^{2+} + I2), Fe^{3+} + S^{2−} (Fe^{2+} + S↓), Fe^{3+} + SO3^{2−} (Fe^{2+} + SO4^{2−}), Cu^{2+} + I^{−} (CuI↓ + I2↓).", "«Без видимых признаков» → H2O2 + Na2SO3; «обесцвечивание без осадка и газа» → KMnO4 + Na2SO3/KNO2 + H2SO4; «бурый осадок» → KMnO4 + Na2SO3 + H2O; «две кислоты» → SO2 + Cl2 + 2H2O."]}}, {"id": "melt_electrolysis", "name": "Физика электролиза и электролиз расплавов", "ref": "07", "idea": "Понимать полярность катода и анода при постоянном токе и безошибочно писать продукты электролиза расплавов галогенидов, щелочей, гидридов и Al2O3 в криолите.", "pre": {"type": "one", "q": "Почему в промышленности алюминий получают электролизом раствора Al2O3 в расплаве криолита Na3AlF6, а не электролизом расплава безводного AlCl3?", "o": ["Безводный AlCl3 имеет молекулярную решётку, возгоняется при ~180 °C и практически не проводит ток в расплаве", "При электролизе расплава AlCl3 на катоде выделяется водород", "AlCl3 не растворяется в криолите", "При электролизе AlCl3 на аноде выделяется фтор"], "a": 0, "ex": "Безводный AlCl3 — ковалентное соединение с молекулярной решёткой: его расплав не содержит ионов и не проводит ток. Криолит Na3AlF6 растворяет Al2O3 и снижает температуру электролиза с >2050 °C до ~950 °C.", "d": {"1": "В расплаве безводного AlCl3 нет воды и водорода.", "2": "Проблема AlCl3 не в криолите, а в отсутствии ионов в его расплаве.", "3": "В AlCl3 нет фтора."}}, "pair": {"type": "one", "cases": [["Электролиз расплава NaOH", "Катод: Na^{+} + e⁻ → Na; Анод: 4OH^{−} − 4e⁻ → O2↑ + 2H2O↑"], ["Электролиз расплава NaH", "Катод: Na^{+} + e⁻ → Na; Анод: 2H^{−} − 2e⁻ → H2↑"]], "q": "Почему при электролизе расплава гидрида натрия NaH водород выделяется на АНОДЕ (+), а не на катоде?", "o": ["В гидриде натрия водород находится в виде аниона H^{−} (СО −1), который движется к положительному аноду и окисляется до H2↑", "При электролизе расплавов водород всегда выделяется на аноде", "Натрий заряжен отрицательно и вытесняет водород к аноду", "При нагревании NaH реагирует с кислородом воздуха"], "a": 0, "ex": "В гидридах металлов водород — отрицательно заряженный гидрид-ион H^{−}. Анионы всегда идут к аноду (+) и там отдают электроны (окисляются): 2H^{−} − 2e⁻ → H2↑."}, "fade": {"q": "Восстанови схему электролиза расплава фторида калия KF:", "steps": ["Для электролиза необходим {постоянный|переменный|высокочастотный} электрический ток.", "К отрицательному электроду — {катоду|аноду} — движутся катионы K^{+}, где идёт процесс {восстановления|окисления}: K^{+} + e⁻ → {K|H2|KOH}.", "К положительному электроду — {аноду|катоду} — движутся анионы F^{−}, где идёт {окисление|восстановление}: 2F^{−} − 2e⁻ → {F2↑|O2↑|HF}."]}, "bug": {"q": "Найди ошибку в утверждениях о физике электролиза и расплавах:", "steps": ["Твёрдый кристаллический NaCl не проводит электрический ток, так как ионы жёстко закреплены в решётке.", "На катоде (–) всегда протекает процесс восстановления, а на аноде (+) — процесс окисления.", "При электролизе расплава NaCl на катоде выделяется водород H2↑, а на аноде — хлор Cl2↑.", "При электролизе расплава 4NaOH → 4Na + O2↑ + 2H2O↑ на катоде образуется металлический натрий."], "bad": 2, "fix": "В расплаве NaCl воды нет, поэтому конкуренции нет: на катоде выделяется металлический натрий Na, а на аноде — хлор Cl2↑ (2NaCl → 2Na + Cl2↑).", "why": "Водород H2 на катоде выделяется только при электролизе водного раствора NaCl; всегда проверяй в условии слово «расплав» или «раствор»."}, "recall": {"q": "Назови по памяти суммарные уравнения электролиза 4 расплавов: NaCl, KF, NaOH и Al2O3 (в криолите).", "points": ["2NaCl(расплав) —электролиз→ 2Na + Cl2↑", "2KF(расплав) —электролиз→ 2K + F2↑", "4NaOH(расплав) —электролиз→ 4Na + O2↑ + 2H2O↑", "2Al2O3(расплав в Na3AlF6) —электролиз→ 4Al + 3O2↑"]}}, {"id": "solution_rules", "name": "Электролиз водных растворов: правила катода и анода", "ref": "08", "idea": "Определять продукты на инертном катоде по 3 зонам ряда напряжений ФИПИ (включая NH4^{+}) и на инертном аноде (включая F^{−} и синтез Кольбе).", "pre": {"type": "one", "q": "Какие продукты выделяются на инертных электродах (катод и анод) при электролизе водного раствора фторида меди(II) CuF2?", "o": ["Катод: только Cu; Анод: O2↑", "Катод: только Cu; Анод: F2↑", "Катод: Cu и H2↑; Анод: O2↑", "Катод: только H2↑; Анод: F2↑"], "a": 0, "ex": "Cu^{2+} стоит после (H2) в ряду напряжений → на катоде только Cu. Фторид-ион F^{−} в водном растворе никогда не окисляется → вместо него окисляется вода до O2↑.", "d": {"1": "Фтор F2 невозможно получить из водного раствора — на аноде окисляется вода до O2↑.", "2": "Медь стоит после водорода, поэтому H2 одновременно с Cu не выделяется.", "3": "Оба электрода определены неверно: Cu после H2, а F^{−} не окисляется в воде."}}, "pair": {"type": "one", "cases": [["Водный раствор Pb(NO3)2", "Свинец Pb стоит ДО (H2) в ряду напряжений ФИПИ"], ["Водный раствор Hg(NO3)2", "Ртуть Hg стоит ПОСЛЕ (H2) в ряду напряжений ФИПИ"]], "q": "Чем отличаются продукты на инертном катоде при электролизе водных растворов Pb(NO3)2 и Hg(NO3)2?", "o": ["В растворе Pb(NO3)2 выделяются Pb и H2↑; в растворе Hg(NO3)2 — только Hg", "В обоих растворах выделяется только металл без водорода", "В растворе Pb(NO3)2 выделяется только H2↑; в растворе Hg(NO3)2 — Hg и H2↑", "В растворе Pb(NO3)2 выделяется только Pb; в растворе Hg(NO3)2 — Hg и H2↑"], "a": 0, "ex": "Свинец Pb завершает среднюю зону (Mn–Pb, до водорода) → на катоде металл и H2↑. Ртуть Hg, как и Cu, Ag, Pt, Au, стоит после (H2) → на катоде только металл."}, "fade": {"q": "Определи продукты на инертных электродах для водных растворов FeCl2, NH4Br и CH3COOK:", "steps": ["FeCl2 (р-р): Fe^{2+} между Al и H2 → на катоде {Fe и H2|только Fe|только H2}; Cl^{−} бескислородный → на аноде {Cl2|O2|H2}.", "NH4Br (р-р): катион NH4^{+} в № 20 ведёт себя как активный металл → на катоде {только H2|NH3 и O2|N2}; на аноде {Br2|O2|HBr}.", "CH3COOK (р-р): K^{+} до Al → на катоде {H2|K|K и H2}; карбоксилат CH3COO^{−} вступает в синтез Кольбе → на аноде {C2H6 и CO2|O2|CH4 и CO2}."]}, "bug": {"q": "Найди ошибочный вывод при решении задания № 20 для водных растворов на инертных электродах:", "steps": ["Для водного раствора NaF на катоде выделяется H2↑, а на аноде — O2↑.", "Для водного раствора KHSO4 на катоде выделяется H2↑, а на аноде — O2↑.", "Для водного раствора ZnSO4 на катоде выделяется только металлический цинк Zn, а на аноде — O2↑.", "Для водного раствора CuCl2 на катоде выделяется только медь Cu, а на аноде — хлор Cl2↑."], "bad": 2, "fix": "Цинк Zn стоит в средней зоне ряда напряжений (между Al и H2), поэтому в задании № 20 для водного раствора ZnSO4 на катоде всегда выделяются «металл и водород» (Zn и H2↑).", "why": "Главная ловушка средней зоны (Mn, Zn, Cr, Fe, Ni, Sn, Pb): пропуск водорода рядом с металлом даёт 0 баллов в № 20."}, "recall": {"q": "Назови по памяти все 3 зоны катода и все 4 группы анионов на инертном аноде в водном растворе.", "points": ["Катод: Li–Al и NH4^{+} → только H2; Mn–Pb → металл и H2; Cu–Au → только металл; H^{+} кислот → H2.", "Анод: Cl^{−}, Br^{−}, I^{−}, S^{2−} → неметалл; F^{−}, оксоанионы и OH^{−} → O2; RCOO^{−} → алкан R–R и CO2 (синтез Кольбе)."]}}, {"id": "summary_electrolysis", "name": "Суммарные уравнения, pH у электродов и активный анод", "ref": "09", "idea": "Собирать полные уравнения электролиза растворов, определять накопление кислоты/щёлочи, этап последовательного электролиза и растворение активного анода.", "pre": {"type": "one", "q": "Как изменится среда раствора (pH) и какие вещества образуются при электролизе водного раствора KCl на инертных электродах?", "o": ["В растворе накапливается щёлочь KOH (pH растёт), выделяются H2↑ и Cl2↑", "В растворе накапливается кислота HCl (pH падает), выделяются K и O2↑", "pH не меняется, идёт только электролиз воды 2H2O → 2H2↑ + O2↑", "В растворе накапливается KClO3 и выделяется O2↑"], "a": 0, "ex": "На катоде восстанавливается вода (2H2O + 2e⁻ → H2↑ + 2OH^{−}), на аноде окисляется Cl^{−} (→ Cl2↑). Оставшиеся K^{+} и OH^{−} образуют щёлочь KOH: 2KCl + 2H2O → H2↑ + Cl2↑ + 2KOH.", "d": {"1": "K^{+} не восстанавливается в воде, а Cl^{−} окисляется сам (без O2 и HCl).", "2": "Электролиз воды идёт в растворах K2SO4, KNO3, KF, но не KCl.", "3": "KClO3 образуется только при смешивании Cl2 с горячим KOH, а не как первичный продукт раздельного электролиза."}}, "pair": {"type": "one", "cases": [["Электролиз раствора CuSO4 с графитовым (инертным) анодом", "2CuSO4 + 2H2O → 2Cu + O2↑ + 2H2SO4"], ["Электролиз раствора CuSO4 с медным (активным) анодом", "Анод: Cu − 2e⁻ → Cu^{2+}; Катод: Cu^{2+} + 2e⁻ → Cu"]], "q": "В чём принципиальная разница между процессами на аноде в этих двух установках?", "o": ["На графитовом аноде окисляется вода до O2↑ (+ H2SO4), а медный анод сам растворяется (Cu − 2e⁻ → Cu^{2+}) без выделения кислорода", "На обоих анодах выделяется кислород O2↑", "Медный анод увеличивает массу за счёт оседания меди", "На графитовом аноде окисляется SO4^{2−} до SO3"], "a": 0, "ex": "Атомы активного (растворимого) анода (Cu, Zn, Ag) отдают электроны легче, чем вода и анионы. На этом основано электролитическое рафинирование меди."}, "fade": {"q": "Собери суммарное уравнение электролиза водного раствора ацетата натрия CH3COONa (синтез Кольбе):", "steps": ["На катоде (–) восстанавливается вода: 2H2O + 2e⁻ → {H2↑|Na|O2↑} + 2OH^{−}.", "На аноде (+) окисляются ацетат-ионы: 2CH3COO^{−} − 2e⁻ → {C2H6↑|CH4↑|C2H4↑} + 2CO2↑.", "В растворе остаются ионы Na^{+} и OH^{−}, поэтому суммарное уравнение: 2CH3COONa + 2H2O → C2H6↑ + 2CO2↑ + H2↑ + {2NaOH|2CH3COOH|Na2CO3}."]}, "bug": {"q": "Найди ошибку в описании электролиза растворов и последовательного электролиза:", "steps": ["В водных растворах Na2SO4, KNO3, NaF, NaOH и H2SO4 суммарно идёт электролиз воды (2H2O → 2H2↑ + O2↑), поэтому массовая доля растворённого вещества растёт.", "При электролизе раствора CuSO4 на инертных электродах в растворе накапливается серная кислота H2SO4 (pH падает).", "Если после полного израсходования CuSO4 в растворе продолжить пропускать ток, процесс электролиза полностью прекращается.", "При электролизе водного раствора HCl на катоде выделяется H2↑, а на аноде — Cl2↑."], "bad": 2, "fix": "После полного расходования соли CuSO4 ток не прекращается — начинается второй этап: электролиз оставшейся воды (2H2O → 2H2↑ + O2↑), и на катоде начинает выделяться H2↑.", "why": "Именно появление водорода на катоде после осаждения всей меди — главный маркер второго этапа электролиза в расчётных задачах № 34."}, "recall": {"q": "Назови по памяти 4 базовых типа суммарных уравнений электролиза растворов и куда сдвигается pH в каждом случае.", "points": ["KCl (р-р): 2KCl + 2H2O → H2↑ + Cl2↑ + 2KOH (pH растёт, щёлочь).", "CuSO4 (р-р): 2CuSO4 + 2H2O → 2Cu + O2↑ + 2H2SO4 (pH падает, кислота).", "CuCl2 (р-р): CuCl2 → Cu + Cl2↑ (вода не участвует, соль расходуется).", "Na2SO4 / KNO3 / NaF / NaOH / H2SO4: 2H2O → 2H2↑ + O2↑ (идёт электролиз воды, концентрация растёт)."]}}, {"id": "kim20_industry", "name": "Промышленное получение веществ и все форматы № 20", "ref": "10", "idea": "Мгновенно выбирать способ промышленного получения любого металла и неметалла электролизом и безошибочно решать все 3 формата таблиц соответствия № 20.", "pre": {"type": "one", "q": "Каким способом электролиза в промышленности получают газообразный фтор F2 и гидроксид натрия NaOH соответственно?", "o": ["F2 — электролиз расплава KF (или KHF2); NaOH — электролиз водного раствора NaCl", "F2 — электролиз водного раствора KF; NaOH — электролиз расплава NaCl", "Оба вещества получают электролизом водных растворов соответствующих солей", "Оба вещества получают электролизом расплавов соответствующих солей"], "a": 0, "ex": "Из водного раствора KF вместо F2 выделится O2, поэтому фтор получают только из расплава. А из расплава NaCl получится Na + Cl2 без NaOH, поэтому NaOH получают электролизом водного раствора NaCl.", "d": {"1": "Перепутаны расплав и раствор для обоих веществ.", "2": "Фтор невозможно получить электролизом водного раствора.", "3": "Из расплава NaCl невозможно получить щёлочь NaOH (нет воды)."}}, "pair": {"type": "one", "cases": [["Получение металлического натрия Na", "Нужен электролиз расплава NaCl (или расплава NaOH)"], ["Получение хлора Cl2, водорода H2 и щёлочи NaOH", "Нужен электролиз водного раствора NaCl"]], "q": "Почему в задании № 20 для получения меди Cu и хлора Cl2 выбирают водный раствор, а для кальция Ca и магния Mg — строго расплав?", "o": ["Ca и Mg стоят до Al (в воде на катоде пойдёт H2 вместо металла), а Cu стоит после H2 и Cl^{−} окисляется сам — водный раствор работает и энергоэкономичнее", "CaCl2 и MgCl2 нерастворимы в воде", "CuCl2 не плавится при нагревании", "Хлор Cl2 не выделяется при электролизе расплава NaCl"], "a": 0, "ex": "Активные металлы (Li–Al) не выделяются из водных растворов (побеждает вода → H2), поэтому для них обязателен расплав. Неактивные металлы (Cu, Ag) и Cl2/Br2/I2 легко и экономично получают из водных растворов."}, "fade": {"q": "Пройди дерево решений промышленного получения веществ электролизом (формат 3 задания № 20):", "steps": ["Калий K и магний Mg стоят до Al → единственный способ: электролиз {расплава хлорида|водного раствора хлорида|водного раствора сульфата}.", "Алюминий Al → единственный способ: электролиз {раствора Al2O3 в расплаве криолита|расплава AlCl3|водного раствора Al2(SO4)3}.", "Кислород O2 → электролиз {водного раствора Na2SO4 / NaOH / NaF|расплава NaCl|водного раствора CuCl2}."]}, "bug": {"q": "Найди ошибку в решении прототипа задания № 20 (продукты электролиза водного раствора на инертных электродах):", "steps": ["AgNO3 (р-р): на катоде только Ag, на аноде O2↑ → «металл и кислород».", "NaF (р-р): на катоде H2↑, на аноде O2↑ → «водород и кислород».", "ZnCl2 (р-р): на катоде Zn и H2↑, на аноде Cl2↑ → «металл, водород и хлор».", "CH3COOK (р-р): на катоде H2↑, на аноде O2↑ → «водород и кислород»."], "bad": 3, "fix": "CH3COOK — соль карбоновой кислоты (ацетат), поэтому на аноде идёт синтез Кольбе с образованием этана C2H6↑ и углекислого газа CO2↑ (а не O2↑!).", "why": "Органические соли (ацетаты, пропионаты) — частая ловушка № 20: на аноде вместо кислорода образуются алкан R–R и CO2↑."}, "recall": {"q": "Назови по памяти чек-лист из 3 вопросов перед записью 3 цифр ответа в задании № 20.", "points": ["1) В условии «расплав» или «водный раствор»?", "2) Спрашивают про катод (–), анод (+), оба электрода или способ получения?", "3) Есть ли среди формул ловушки: F^{−}, NH4^{+}, металл средней активности (Mn–Pb), ацетат (RCOO^{−}) или Al2O3 в криолите vs AlCl3?"]}}], "figs": {}, "tab": [{"id": "tab_ox_roles", "ref": "01.5", "k": "Вещество (элемент)", "km": "веществом", "lv3": ["FeS2 (S)", "OF2 (O)", "CaH2 (H)", "NH4NO3 (N)"], "cols": [{"t": "Степень окисления элемента", "sk": "ox_state", "n": 19, "q": "Чему равна степень окисления указанного элемента в {x}?", "m": "степенью окисления", "mq": "Выберите {k} вещества, в которых указанный элемент имеет степень окисления {v}."}, {"t": "Прогноз ОВ-свойств элемента", "sk": "ox_state", "n": 19, "q": "Какие ОВ-свойства может проявлять указанный элемент в {x}?", "m": "ОВ-свойствами элемента", "mq": "Выберите {k} вещества, где указанный элемент проявляет свойства: {v}."}], "rows": [["KMnO4 (Mn)", "+7", "Только окислитель"], ["K2Cr2O7 (Cr)", "+6", "Только окислитель"], ["OF2 (O)", "+2", "Только окислитель"], ["KI (I)", "−1", "Только восстановитель"], ["H2S (S)", "−2", "Только восстановитель"], ["CaH2 (H)", "−1", "Только восстановитель"], ["FeS2 (S)", "−1", "И окислитель, и восстановитель (промежуточная СО)"], ["H2O2 (O)", "−1", "И окислитель, и восстановитель (промежуточная СО)"], ["KNO2 (N)", "+3", "И окислитель, и восстановитель (промежуточная СО)"], ["Na2SO3 (S)", "+4", "И окислитель, и восстановитель (промежуточная СО)"]], "rw": {"FeS2 (S)": "В пирите дисульфид-ион S2^{2−} даёт сере промежуточную СО −1 (хотя сам пирит как вещество в ЕГЭ работает как сильный восстановитель).", "OF2 (O)": "Фтор более электроотрицателен, чем кислород → F^{−1} и O^{+2} (высшая СО кислорода).", "CaH2 (H)": "В гидридах металлов водород имеет минимальную СО −1 (только восстановитель)."}}, {"id": "tab_chameleons19", "ref": "02.6", "k": "Реакция с «хамелеоном»", "km": "реакцией", "lv3": ["2F2 + 2H2O → 4HF + O2↑ (роль H2O)", "2Na + 2NH3 → 2NaNH2 + H2↑ (роль NH3)", "CH2=CH2 + H2 → C2H6 (роль C2H4)"], "cols": [{"t": "Роль указанного вещества в реакции", "sk": "kim19_traps", "n": 19, "q": "Какую роль играет указанное вещество в реакции: {x}?", "m": "ролью вещества", "mq": "Выберите {k} реакции, в которых указанное вещество выступает в роли: {v}."}], "rows": [["2Na + 2H2O → 2NaOH + H2↑ (роль H2O)", "Только окислитель"], ["2F2 + 2H2O → 4HF + O2↑ (роль H2O)", "Только восстановитель"], ["2KMnO4 + 3Na2SO3 + H2O → 2MnO2↓ + 3Na2SO4 + 2KOH (роль H2O)", "Не проявляет ОВ-свойств (среда / не-ОВР)"], ["Fe + 2HCl → FeCl2 + H2↑ (роль HCl)", "Только окислитель"], ["MnO2 + 4HCl(конц.) → MnCl2 + Cl2↑ + 2H2O (роль HCl)", "Только восстановитель"], ["NaOH + HCl → NaCl + H2O (роль HCl)", "Не проявляет ОВ-свойств (среда / не-ОВР)"], ["2Na + 2NH3 → 2NaNH2 + H2↑ (роль NH3)", "Только окислитель"], ["4NH3 + 3O2 → 2N2 + 6H2O (роль NH3)", "Только восстановитель"], ["NH3 + HCl → NH4Cl (роль NH3)", "Не проявляет ОВ-свойств (среда / не-ОВР)"], ["2H2O2 —MnO2→ 2H2O + O2↑ (роль H2O2)", "И окислитель, и восстановитель"], ["CH2=CH2 + H2 → C2H6 (роль C2H4)", "Только окислитель"], ["CH3CHO + 2[Ag(NH3)2]OH → CH3COONH4 + 2Ag↓ + 3NH3↑ + H2O (роль CH3CHO)", "Только восстановитель"]], "rw": {"2F2 + 2H2O → 4HF + O2↑ (роль H2O)": "Фтор окисляет кислород воды O^{−2} → O2^{0}, поэтому H2O — восстановитель.", "2Na + 2NH3 → 2NaNH2 + H2↑ (роль NH3)": "Щелочной металл восстанавливает H^{+1} аммиака до H2↑, поэтому NH3 — окислитель.", "CH2=CH2 + H2 → C2H6 (роль C2H4)": "При гидрировании углерод понижает СО (−2 → −3), значит алкен — окислитель."}}, {"id": "tab_mn_cr_ph", "ref": "04.14", "k": "Окислитель и среда (pH)", "km": "системой", "lv3": ["KMnO4 + H2O", "KMnO4 + KOH", "K2CrO4 + KOH (с восстановителем)"], "cols": [{"t": "Продукт восстановления металла", "sk": "ph_mn_cr", "n": 29, "q": "Какой продукт восстановления металла образуется в системе {x}?", "m": "продуктом восстановления", "mq": "Выберите {k} системы, дающие продукт: {v}."}, {"t": "Визуальный признак", "sk": "ph_mn_cr", "n": 29, "q": "Какой визуальный признак соответствует переходу металла в системе {x}?", "m": "визуальным признаком", "mq": "Выберите {k} системы с признаком: {v}."}], "rows": [["KMnO4 + H2SO4(разб.)", "MnSO4 (Mn^{2+})", "Обесцвечивание раствора (без осадка)"], ["KMnO4 + KHSO4", "MnSO4 (Mn^{2+})", "Обесцвечивание раствора (без осадка)"], ["KMnO4 + H2O", "MnO2↓ (Mn^{+4})", "Выпадение бурого осадка"], ["KMnO4 + KOH", "K2MnO4 (Mn^{+6})", "Изумрудно-зелёный раствор (без осадка)"], ["K2Cr2O7 + H2SO4(разб.)", "Cr2(SO4)3 (Cr^{3+})", "Зелёный раствор (без осадка)"], ["K2Cr2O7 + H2O", "Cr(OH)3↓ (Cr^{+3})", "Выпадение серо-зелёного осадка"], ["K2CrO4 + KOH (с восстановителем)", "K[Cr(OH)4] / K3[Cr(OH)6]", "Изумрудно-зелёный раствор (без осадка)"]], "rw": {"KMnO4 + H2O": "В нейтральной среде Mn^{+7} + 3e⁻ → MnO2↓ (бурый осадок) + щёлочь.", "KMnO4 + KOH": "В щёлочи Mn^{+7} + 1e⁻ → K2MnO4 (изумрудно-зелёный раствор).", "K2CrO4 + KOH (с восстановителем)": "Амфотерный Cr^{+3} в избытке щёлочи образует растворимый гидроксокомплекс."}}, {"id": "tab_acids_ox", "ref": "05.3", "k": "Пара реагентов", "km": "парой реагентов", "lv3": ["Fe + HNO3(конц., хол.)", "NaCl(тв.) + H2SO4(конц.)", "Zn + NaNO3 + NaOH(р-р, t°)"], "cols": [{"t": "Главный продукт восстановления / результат", "sk": "acids_h2o2_hal", "n": 29, "q": "Какой продукт восстановления окислителя (или результат) характерен для пары {x}?", "m": "продуктом восстановления", "mq": "Выберите {k} пары, дающие результат: {v}."}], "rows": [["Cu + HNO3(конц.)", "NO2↑ (бурый газ)"], ["Cu2S + HNO3(конц.)", "NO2↑ (бурый газ)"], ["Cu + HNO3(разб.)", "NO↑ (бесцветный газ, буреет на воздухе)"], ["Cu + H2SO4(конц., t°)", "SO2↑ (газ с резким запахом)"], ["NaBr(тв.) + H2SO4(конц., t°)", "SO2↑ (газ с резким запахом)"], ["NaI(тв.) + H2SO4(конц.)", "H2S↑ (запах тухлых яиц)"], ["Zn + NaNO3 + NaOH(р-р, t°)", "NH3↑ (резкий запах, щелочная среда)"], ["Fe + HNO3(конц., хол.)", "Пассивация (реакция не идёт)"], ["Al + H2SO4(конц., хол.)", "Пассивация (реакция не идёт)"], ["NaCl(тв.) + H2SO4(конц., t°)", "Не ОВР (обмен до HCl↑)"]], "rw": {"Fe + HNO3(конц., хол.)": "Холодные концентрированные HNO3 и H2SO4 пассивируют Fe, Al, Cr.", "NaCl(тв.) + H2SO4(конц., t°)": "Cl^{−} не окисляется H2SO4(конц.) — идёт обычный обмен с выделением HCl↑.", "Zn + NaNO3 + NaOH(р-р, t°)": "Нитрат в щёлочи с Zn или Al восстанавливается до NH3↑."}}, {"id": "tab_signs29", "ref": "06.9", "k": "Вещество / реакция в № 29", "km": "веществом или реакцией", "lv3": ["H2O2 + Na2SO3", "CuI↓", "NO↑", "Cr(OH)3↓"], "cols": [{"t": "Внешний признак в пробирке", "sk": "reducers_nav29", "n": 29, "q": "Какой внешний признак характерен для {x} в заданиях № 29?", "m": "внешним признаком", "mq": "Выберите {k} вещества или системы с признаком: {v}."}], "rows": [["O2↑", "Бесцветный газ без запаха"], ["CO2↑", "Бесцветный газ без запаха"], ["NO2↑", "Бурый газ с резким запахом"], ["Cl2↑", "Жёлто-зелёный газ с резким запахом"], ["NO↑", "Бесцветный газ, буреющий на воздухе"], ["MnO2↓", "Бурый осадок"], ["Fe(OH)3↓", "Бурый осадок"], ["S↓", "Жёлтый осадок"], ["CuI↓", "Белый осадок"], ["Cr(OH)3↓", "Серо-зелёный осадок"], ["K2MnO4 (р-р)", "Зелёный раствор (без осадка)"], ["Cr2(SO4)3 (р-р)", "Зелёный раствор (без осадка)"], ["H2O2 + Na2SO3", "Без видимых признаков"], ["H2O2 + KNO2", "Без видимых признаков"]], "rw": {"H2O2 + Na2SO3": "H2O2 + Na2SO3 → Na2SO4 + H2O: все вещества бесцветны и растворимы.", "CuI↓": "Белый осадок CuI↓ выпадает вместе с бурым иодом I2 в реакции 2CuSO4 + 4KI.", "NO↑": "Бесцветный оксид азота(II) мгновенно окисляется кислородом воздуха до бурого NO2."}}, {"id": "tab_melts", "ref": "07.10", "k": "Расплав электролита", "km": "расплавом", "lv3": ["NaH (расплав)", "NaOH (расплав)", "Al2O3 в расплаве криолита"], "cols": [{"t": "Продукт на катоде (–)", "sk": "melt_electrolysis", "n": 20, "q": "Какой продукт выделяется на катоде (–) при электролизе расплава {x}?", "m": "продуктом на катоде", "mq": "Выберите {k} расплавы, дающие на катоде {v}."}, {"t": "Продукт на аноде (+)", "sk": "melt_electrolysis", "n": 20, "q": "Какой продукт выделяется на аноде (+) при электролизе расплава {x}?", "m": "продуктом на аноде", "mq": "Выберите {k} расплавы, дающие на аноде {v}."}], "rows": [["NaCl (расплав)", "Na", "Cl2↑"], ["KF (расплав)", "K", "F2↑"], ["MgCl2 (расплав)", "Mg", "Cl2↑"], ["NaOH (расплав)", "Na", "O2↑ и H2O↑"], ["NaH (расплав)", "Na", "H2↑"], ["Al2O3 в расплаве криолита", "Al", "O2↑"]], "rw": {"NaH (расплав)": "В гидриде водород — анион H^{−}, поэтому H2↑ выделяется на аноде (+).", "NaOH (расплав)": "На аноде окисляются OH^{−}: 4OH^{−} − 4e⁻ → O2↑ + 2H2O↑.", "Al2O3 в расплаве криолита": "Криолит Na3AlF6 снижает температуру плавления Al2O3 до ~950 °C."}}, {"id": "tab_solutions20", "ref": "08.8", "k": "Водный раствор электролита", "km": "водным раствором", "lv3": ["NaF (р-р)", "Fe(NO3)2 (р-р)", "Pb(NO3)2 (р-р)", "NH4Cl (р-р)", "CH3COOK (р-р)"], "cols": [{"t": "Продукт на инертном катоде (–)", "sk": "solution_rules", "n": 20, "q": "Что выделяется на инертном катоде (–) при электролизе водного раствора {x}?", "m": "продуктом на катоде", "mq": "Выберите {k} растворы, у которых на катоде выделяется: {v}."}, {"t": "Продукт на инертном аноде (+)", "sk": "solution_rules", "n": 20, "q": "Что выделяется на инертном аноде (+) при электролизе водного раствора {x}?", "m": "продуктом на аноде", "mq": "Выберите {k} растворы, у которых на аноде выделяется: {v}."}], "rows": [["NaF (р-р)", "Только H2↑", "O2↑"], ["Na2SO4 (р-р)", "Только H2↑", "O2↑"], ["KCl (р-р)", "Только H2↑", "Галоген (Cl2/Br2/I2)"], ["NH4Cl (р-р)", "Только H2↑", "Галоген (Cl2/Br2/I2)"], ["CH3COOK (р-р)", "Только H2↑", "Алкан (C2H6) и CO2↑"], ["Fe(NO3)2 (р-р)", "Металл и H2↑", "O2↑"], ["Pb(NO3)2 (р-р)", "Металл и H2↑", "O2↑"], ["ZnCl2 (р-р)", "Металл и H2↑", "Галоген (Cl2/Br2/I2)"], ["CuCl2 (р-р)", "Только металл", "Галоген (Cl2/Br2/I2)"], ["AgNO3 (р-р)", "Только металл", "O2↑"], ["Hg(NO3)2 (р-р)", "Только металл", "O2↑"], ["CuF2 (р-р)", "Только металл", "O2↑"]], "rw": {"NaF (р-р)": "F^{−} в воде не окисляется → на аноде O2↑.", "Fe(NO3)2 (р-р)": "Fe стоит между Al и H2 → на катоде Fe и H2↑.", "Pb(NO3)2 (р-р)": "Pb стоит ДО (H2) → на катоде Pb и H2↑.", "NH4Cl (р-р)": "В № 20 NH4^{+} ведёт себя как активный металл → на катоде только H2↑.", "CH3COOK (р-р)": "Синтез Кольбе: 2CH3COO^{−} − 2e⁻ → C2H6↑ + 2CO2↑."}}, {"id": "tab_summary_ph", "ref": "09.4", "k": "Водный раствор (инертные электроды)", "km": "раствором", "lv3": ["CH3COONa (р-р)", "Na2SO4 (р-р)", "CuSO4 (р-р)"], "cols": [{"t": "Что накапливается в растворе (и как меняется pH)", "sk": "summary_electrolysis", "n": 20, "q": "Что накапливается в растворе при электролизе {x} на инертных электродах?", "m": "изменением состава раствора", "mq": "Выберите {k} растворы с результатом: {v}."}], "rows": [["KCl (р-р)", "Накапливается щёлочь (pH растёт)"], ["NaBr (р-р)", "Накапливается щёлочь (pH растёт)"], ["CH3COONa (р-р)", "Накапливается щёлочь (pH растёт)"], ["CuSO4 (р-р)", "Накапливается кислота (pH падает)"], ["AgNO3 (р-р)", "Накапливается кислота (pH падает)"], ["CuCl2 (р-р)", "Соль расходуется, вода не разлагается"], ["Na2SO4 (р-р)", "Идёт электролиз воды (соль концентрируется)"], ["NaF (р-р)", "Идёт электролиз воды (соль концентрируется)"], ["H2SO4 (р-р)", "Идёт электролиз воды (кислота концентрируется)"]], "rw": {"CH3COONa (р-р)": "На катоде H2↑ + 2OH^{−}, поэтому в растворе накапливается NaOH.", "Na2SO4 (р-р)": "H^{+} и OH^{−} нейтрализуются; суммарно 2H2O → 2H2↑ + O2↑.", "CuSO4 (р-р)": "На аноде O2↑ + 4H^{+}, поэтому в растворе накапливается H2SO4."}}, {"id": "tab_industry20", "ref": "10.5", "k": "Получаемое вещество", "km": "веществом", "lv3": ["Al", "F2", "NaOH", "K"], "cols": [{"t": "Промышленный способ электролиза (№ 20)", "sk": "kim20_industry", "n": 20, "q": "Каким способом электролиза в промышленности получают {x}?", "m": "способом получения электролизом", "mq": "Выберите {k} вещества, получаемые способом: {v}."}], "rows": [["Na", "Электролиз расплава галогенида (или щёлочи)"], ["K", "Электролиз расплава галогенида (или щёлочи)"], ["Ca", "Электролиз расплава галогенида (или щёлочи)"], ["Mg", "Электролиз расплава галогенида (или щёлочи)"], ["F2", "Электролиз расплава фторида (KF / KHF2)"], ["Al", "Электролиз раствора Al2O3 в расплаве криолита Na3AlF6"], ["Cl2", "Электролиз водного раствора соли (NaCl / KCl)"], ["NaOH", "Электролиз водного раствора соли (NaCl / KCl)"], ["H2", "Электролиз водного раствора соли (NaCl / KCl)"], ["Cu", "Электролиз водного раствора соли (CuSO4 / CuCl2)"], ["Ag", "Электролиз водного раствора соли (AgNO3)"], ["O2", "Электролиз водного раствора оксосоли / щёлочи / H2SO4"]], "rw": {"Al": "Из расплава AlCl3 получить Al нельзя — нужен Al2O3 в расплаве криолита.", "F2": "Из водного раствора фторида выделится O2, поэтому только расплав.", "NaOH": "Из расплава NaCl щёлочь не получится — нужен водный раствор NaCl."}}], "rx": [{"id": "rx01_kmno4_hcl", "sk": "balance_fipi", "ref": "03.5", "n": 29, "lvl": 1, "l": ["KMnO4", "HCl"], "r": ["KCl", "MnCl2", "Cl2", "H2O"], "c": [2, 16, 2, 2, 5, 8], "ox": 0, "red": 1, "if": "конц. HCl (выделение жёлто-зелёного газа Cl2↑)", "bad": [["MnO2", "В сильнокислой среде HCl перманганат восстанавливается до MnCl2 (Mn^{+2}), а не до MnO2."], ["KClO3", "Хлорид-ион окисляется перманганатом до простого вещества Cl2↑."]], "why": "Баланс с удвоением: Mn^{+7} + 5e⁻ → Mn^{+2} (×2), 2Cl^{−1} − 2e⁻ → Cl2^{0} (×5). Часть HCl (6 моль из 16) идёт на связывание K^{+} и Mn^{2+}."}, {"id": "rx02_fes2_o2", "sk": "balance_fipi", "ref": "03.9", "n": 29, "lvl": 3, "l": ["FeS2", "O2"], "r": ["Fe2O3", "SO2"], "c": [4, 11, 2, 8], "ox": 1, "red": 0, "if": "t°, обжиг пирита (двойное окисление)", "bad": [["FeO", "В избытке кислорода при обжиге пирита железо окисляется до Fe2O3 (+3)."], ["SO3", "При обжиге пирита без катализатора сера окисляется до SO2 (+4), а не до SO3."]], "why": "Двойное окисление: 1 формульная единица FeS2 отдаёт 1e⁻ (Fe^{+2}→Fe^{+3}) + 10e⁻ (2S^{−1}→2S^{+4}) = 11e⁻; O2^{0} + 4e⁻ → 2O^{−2}. НОК(11, 4) = 44."}, {"id": "rx03_cl2_koh_hot", "sk": "balance_fipi", "ref": "03.11", "n": 19, "lvl": 2, "l": ["Cl2", "KOH"], "r": ["KCl", "KClO3", "H2O"], "c": [3, 6, 5, 1, 3], "if": "горячий раствор щёлочи, t° (диспропорционирование)", "bad": [["KClO", "Гипохлорит KClO образуется в холодной щёлочи; при нагревании он диспропорционирует до хлората KClO3."], ["KClO4", "Перхлорат в реакции хлора с горячей щёлочью не образуется."]], "why": "Диспропорционирование Cl2 при нагревании: Cl^{0} + 1e⁻ → Cl^{−1} (×5), Cl^{0} − 5e⁻ → Cl^{+5} (×1). Коэффициенты ставим справа налево: 5KCl + KClO3 → 3Cl2."}, {"id": "rx04_kmno4_na2so3_h2so4", "sk": "ph_mn_cr", "ref": "04.8", "n": 29, "lvl": 1, "l": ["KMnO4", "Na2SO3", "H2SO4"], "r": ["MnSO4", "Na2SO4", "K2SO4", "H2O"], "c": [2, 5, 3, 2, 5, 1, 3], "ox": 0, "red": 1, "if": "разб. H2SO4, кислая среда (обесцвечивание без осадка и газа)", "bad": [["MnO2", "В кислой среде Mn^{+7} восстанавливается до бесцветной соли MnSO4."], ["K2MnO4", "Зелёный манганат образуется только в щелочной среде."], ["SO2", "Сульфит окисляется перманганатом до сульфата SO4^{2−}."]], "why": "Mn^{+7} + 5e⁻ → Mn^{+2} (×2), S^{+4} − 2e⁻ → S^{+6} (×5). Эталон признака «обесцвечивание раствора без осадка и газа»."}, {"id": "rx05_kmno4_k2so3_khso4", "sk": "ph_mn_cr", "ref": "04.8", "n": 29, "lvl": 3, "l": ["KMnO4", "K2SO3", "KHSO4"], "r": ["MnSO4", "K2SO4", "H2O"], "c": [2, 5, 6, 2, 9, 3], "ox": 0, "red": 1, "if": "кислая соль KHSO4 вместо H2SO4 (раствор двух солей)", "bad": [["MnO2", "KHSO4 создаёт кислую среду, поэтому марганец восстанавливается до MnSO4."], ["H2SO4", "Протоны H^{+} из KHSO4 связываются с кислородом перманганата в воду H2O."]], "why": "Гидросульфат калия KHSO4 заменяет H2SO4(разб.) и не вносит лишнего катиона — в продуктах ровно две соли (MnSO4 и K2SO4)."}, {"id": "rx06_kmno4_na2so3_h2o", "sk": "ph_mn_cr", "ref": "04.8", "n": 29, "lvl": 2, "l": ["KMnO4", "Na2SO3", "H2O"], "r": ["MnO2", "Na2SO4", "KOH"], "c": [2, 3, 1, 2, 3, 2], "ox": 0, "red": 1, "if": "нейтральная среда H2O (бурый осадок MnO2↓ + щёлочь)", "bad": [["MnSO4", "В нейтральной среде перманганат восстанавливается до бурого осадка MnO2↓."], ["K2MnO4", "Зелёный манганат устойчив только в избытке щёлочи KOH."]], "why": "Mn^{+7} + 3e⁻ → Mn^{+4} (×2), S^{+4} − 2e⁻ → S^{+6} (×3). В нейтральной среде выпадает бурый осадок MnO2↓ и образуется щёлочь KOH."}, {"id": "rx07_kmno4_na2so3_koh", "sk": "ph_mn_cr", "ref": "04.8", "n": 29, "lvl": 2, "l": ["KMnO4", "Na2SO3", "KOH"], "r": ["K2MnO4", "Na2SO4", "H2O"], "c": [2, 1, 2, 2, 1, 1], "ox": 0, "red": 1, "if": "щелочная среда KOH (изумрудно-зелёный раствор без осадка)", "bad": [["MnO2", "В избытке щёлочи Mn^{+7} восстанавливается только до зелёного манганата K2MnO4."], ["Mn(OH)2", "В щелочной среде марганец останавливается на СО +6."]], "why": "Mn^{+7} + 1e⁻ → Mn^{+6} (×2), S^{+4} − 2e⁻ → S^{+6} (×1). Малиновый раствор становится изумрудно-зелёным без осадка и газа."}, {"id": "rx08_k2cr2o7_koh_no_ovr", "sk": "ph_mn_cr", "ref": "04.12", "n": 19, "lvl": 2, "l": ["K2Cr2O7", "KOH"], "r": ["K2CrO4", "H2O"], "c": [1, 2, 2, 1], "if": "щелочная среда — переход дихромата в хромат (НЕ ОВР!)", "bad": [["K3[Cr(OH)6]", "Без восстановителя Cr^{+6} не восстанавливается до Cr^{+3} — это не ОВР."], ["Cr(OH)3", "Осадок Cr(OH)3 без восстановителя не образуется."]], "why": "Оранжевый дихромат переходит в жёлтый хромат без изменения степени окисления (везде Cr^{+6})."}, {"id": "rx09_k3croh6_h2o2", "sk": "ph_mn_cr", "ref": "04.16", "n": 29, "lvl": 3, "l": ["K3[Cr(OH)6]", "H2O2"], "r": ["K2CrO4", "KOH", "H2O"], "c": [2, 3, 2, 2, 8], "ox": 1, "red": 0, "if": "щелочная среда (окисление Cr^{+3} до жёлтого хромата без газа и осадка)", "bad": [["K2Cr2O7", "В щелочной среде хром(+6) существует только в виде жёлтого хромата K2CrO4."], ["O2", "Здесь H2O2 — окислитель (O^{−1} → O^{−2}), поэтому кислород O2 не выделяется."]], "why": "Cr^{+3} − 3e⁻ → Cr^{+6} (×2), 2O^{−1} + 2e⁻ → 2O^{−2} (×3). Изумрудно-зелёный раствор становится жёлтым без газа и осадка."}, {"id": "rx10_demo2027_k2cr2o7_ki", "sk": "ph_mn_cr", "ref": "04.19", "n": 29, "lvl": 3, "l": ["K2Cr2O7", "KI", "H2SO4"], "r": ["I2", "Cr2(SO4)3", "K2SO4", "H2O"], "c": [1, 6, 7, 3, 1, 4, 7], "ox": 0, "red": 1, "if": "разб. H2SO4 (эталон Демоверсии ЕГЭ-2027: простое вещество + 2 соли)", "bad": [["Cr(OH)3", "В сернокислой среде образуется растворимый сульфат Cr2(SO4)3."], ["KIO3", "Иодид-ион окисляется дихроматом в кислоте до простого вещества I2↓."]], "why": "Эталон Демо-2027: 2Cr^{+6} + 6e⁻ → 2Cr^{+3} (×1), 2I^{−1} − 2e⁻ → I2^{0} (×3). Простое вещество I2 и ровно две соли (Cr2(SO4)3 и K2SO4)."}, {"id": "rx11_cu_hno3_conc", "sk": "acids_h2o2_hal", "ref": "05.4", "n": 29, "lvl": 1, "l": ["Cu", "HNO3"], "r": ["Cu(NO3)2", "NO2", "H2O"], "c": [1, 4, 1, 2, 2], "ox": 1, "red": 0, "if": "конц. HNO3 (выделение бурого газа NO2↑)", "bad": [["H2", "Азотная кислота любой концентрации с металлами не выделяет водород H2."], ["NO", "Бесцветный NO выделяется с разбавленной HNO3, а с концентрированной — бурый NO2↑."]], "why": "Cu^{0} − 2e⁻ → Cu^{+2} (×1), N^{+5} + 1e⁻ → N^{+4} (×2). Голубой раствор Cu(NO3)2 и бурый газ «лисий хвост» NO2↑."}, {"id": "rx12_cu_hno3_dil", "sk": "acids_h2o2_hal", "ref": "05.4", "n": 29, "lvl": 1, "l": ["Cu", "HNO3"], "r": ["Cu(NO3)2", "NO", "H2O"], "c": [3, 8, 3, 2, 4], "ox": 1, "red": 0, "if": "разб. HNO3 (бесцветный газ NO↑, буреющий на воздухе)", "bad": [["H2", "В азотной кислоте окислитель — N^{+5}, а не H^{+}."], ["NO2", "Бурый газ NO2 образуется с концентрированной HNO3."]], "why": "Cu^{0} − 2e⁻ → Cu^{+2} (×3), N^{+5} + 3e⁻ → N^{+2} (×2). Проверка O: 24 = 18 + 2 + 4."}, {"id": "rx13_cu_h2so4_conc", "sk": "acids_h2o2_hal", "ref": "05.4", "n": 29, "lvl": 1, "l": ["Cu", "H2SO4"], "r": ["CuSO4", "SO2", "H2O"], "c": [1, 2, 1, 1, 2], "ox": 1, "red": 0, "if": "конц. H2SO4, t° (газ с резким запахом SO2↑)", "bad": [["H2", "Медь стоит после водорода и не вытесняет H2; конц. H2SO4 окисляет за счёт S^{+6}."], ["H2S", "Малоактивная медь восстанавливает S^{+6} только до SO2↑, а не до H2S↑."]], "why": "Cu^{0} − 2e⁻ → Cu^{+2} (×1), S^{+6} + 2e⁻ → S^{+4} (×1). Растворение меди при нагревании с выделением SO2↑."}, {"id": "rx14_cu2s_hno3_conc", "sk": "acids_h2o2_hal", "ref": "05.4", "n": 29, "lvl": 3, "l": ["Cu2S", "HNO3"], "r": ["Cu(NO3)2", "CuSO4", "NO2", "H2O"], "c": [1, 12, 1, 1, 10, 6], "ox": 1, "red": 0, "if": "конц. HNO3 (двойное окисление Cu2S, растворение чёрного осадка)", "bad": [["S", "Концентрированная HNO3 окисляет сульфидную серу полностью до сульфата SO4^{2−}."], ["Cu2SO4", "Медь(+1) в конц. HNO3 полностью окисляется до меди(+2)."]], "why": "Двойное окисление: 2Cu^{+1} − 2e⁻ → 2Cu^{+2} и S^{−2} − 8e⁻ → S^{+6} (всего −10e⁻); N^{+5} + 1e⁻ → N^{+4} (×10)."}, {"id": "rx15_zn_nano3_naoh", "sk": "acids_h2o2_hal", "ref": "05.7", "n": 29, "lvl": 3, "l": ["Zn", "NaNO3", "NaOH", "H2O"], "r": ["Na2[Zn(OH)4]", "NH3"], "c": [4, 1, 7, 6, 4, 1], "ox": 1, "red": 0, "if": "щёлочь, t° (восстановление нитрата до NH3↑ и гидроксокомплекс)", "bad": [["Zn(OH)2", "В избытке щёлочи амфотерный цинк переходит в растворимый комплекс Na2[Zn(OH)4]."], ["NO2", "В щелочной среде активный металл восстанавливает нитрат до аммиака NH3↑."]], "why": "Zn^{0} − 2e⁻ → Zn^{+2} (×4), N^{+5} + 8e⁻ → N^{−3} (×1). Выделяется газ с резким запахом NH3↑."}, {"id": "rx16_cl2_kbr", "sk": "acids_h2o2_hal", "ref": "05.13", "n": 19, "lvl": 1, "l": ["Cl2", "KBr"], "r": ["KCl", "Br2"], "c": [1, 2, 2, 1], "ox": 0, "red": 1, "if": "водный раствор (ряд активности галогенов Cl2 > Br2)", "bad": [["KBrO3", "В нейтральном водном растворе хлор просто вытесняет свободный бром Br2."], ["HBr", "Бром выделяется в виде простого вещества Br2 (бурое окрашивание раствора)."]], "why": "Более активный галоген Cl2 окисляет бромид-ион: Cl2^{0} + 2e⁻ → 2Cl^{−1}, 2Br^{−1} − 2e⁻ → Br2^{0}."}, {"id": "rx17_br2_ki", "sk": "acids_h2o2_hal", "ref": "05.13", "n": 19, "lvl": 1, "l": ["Br2", "KI"], "r": ["KBr", "I2"], "c": [1, 2, 2, 1], "ox": 0, "red": 1, "if": "водный раствор (ряд активности галогенов Br2 > I2)", "bad": [["KIO3", "Бром вытесняет свободный иод I2↓ из раствора иодида."], ["HI", "Образуются соль KBr и простое вещество I2↓."]], "why": "Более активный галоген Br2 вытесняет менее активный I2 из раствора иодида."}, {"id": "rx18_kclo3_hcl", "sk": "acids_h2o2_hal", "ref": "05.17", "n": 29, "lvl": 2, "l": ["KClO3", "HCl"], "r": ["KCl", "Cl2", "H2O"], "c": [1, 6, 1, 3, 3], "ox": 0, "red": 1, "if": "конц. HCl (сопропорционирование хлора)", "bad": [["KClO", "В сильнокислой среде гипохлорит не существует и сразу даёт Cl2↑."], ["O2", "KClO3 окисляет Cl^{−1} до Cl2↑, кислород не выделяется."]], "why": "Сопропорционирование: Cl^{+5} + 5e⁻ → Cl^{0} (×1), Cl^{−1} − 1e⁻ → Cl^{0} (×5). Справа 6 атомов хлора → 3Cl2↑."}, {"id": "rx19_kclo3_ki_h2so4", "sk": "acids_h2o2_hal", "ref": "05.17", "n": 29, "lvl": 2, "l": ["KClO3", "KI", "H2SO4"], "r": ["KCl", "I2", "K2SO4", "H2O"], "c": [1, 6, 3, 1, 3, 3, 3], "ox": 0, "red": 1, "if": "разб. H2SO4 (простое вещество I2↓ и две соли)", "bad": [["Cl2", "Хлорат восстанавливается до Cl^{−1} (KCl), а окисляется более сильный восстановитель I^{−1} до I2↓."], ["KIO3", "В кислой среде иодид окисляется до простого вещества I2↓."]], "why": "Cl^{+5} + 6e⁻ → Cl^{−1} (×1), 2I^{−1} − 2e⁻ → I2^{0} (×3). Образуются I2↓ и две соли (KCl и K2SO4)."}, {"id": "rx20_kio3_ki_h2so4", "sk": "acids_h2o2_hal", "ref": "05.17", "n": 29, "lvl": 3, "l": ["KIO3", "KI", "H2SO4"], "r": ["I2", "K2SO4", "H2O"], "c": [1, 5, 3, 3, 3, 3], "ox": 0, "red": 1, "if": "разб. H2SO4 (сопропорционирование иода: простое вещество и ОДНА соль)", "bad": [["HI", "В присутствии окислителя KIO3 иодид окисляется до простого вещества I2↓."], ["O2", "Кислород не меняет СО — идёт сопропорционирование I^{+5} и I^{−1} в I2^{0}."]], "why": "I^{+5} + 5e⁻ → I^{0} (×1), I^{−1} − 1e⁻ → I^{0} (×5) → 3I2↓. Идеальный ответ на фильтр «простое вещество и ОДНА соль»!"}, {"id": "rx21_fecl3_ki", "sk": "reducers_nav29", "ref": "06.6", "n": 29, "lvl": 2, "l": ["FeCl3", "KI"], "r": ["FeCl2", "I2", "KCl"], "c": [2, 2, 2, 1, 2], "ox": 0, "red": 1, "if": "водный раствор без третьей среды (прочерк в таблице растворимости → ОВР)", "bad": [["FeI3", "Иодид железа(III) не существует в растворе из-за мгновенной ОВР."], ["Cl2", "Железо(+3) окисляет иодид-ион, а не хлорид-ион."]], "why": "Fe^{+3} + 1e⁻ → Fe^{+2} (×2), 2I^{−1} − 2e⁻ → I2^{0} (×1). Классическая ОВР без добавления кислоты или щёлочи."}, {"id": "rx22_cuso4_ki", "sk": "reducers_nav29", "ref": "06.6", "n": 29, "lvl": 3, "l": ["CuSO4", "KI"], "r": ["CuI", "I2", "K2SO4"], "c": [2, 4, 2, 1, 2], "ox": 0, "red": 1, "if": "водный раствор (белый осадок CuI↓ и простое вещество I2↓)", "bad": [["CuI2", "CuI2 в водном растворе не существует — мгновенно распадается на CuI↓ и I2↓."], ["Cu", "Медь(+2) восстанавливается иодидом только до +1 (белый осадок CuI↓), а не до металла."]], "why": "Cu^{+2} + 1e⁻ → Cu^{+1} (×2), 2I^{−1} − 2e⁻ → I2^{0} (×1). Выпадают белый осадок CuI↓ и бурый иод I2↓."}, {"id": "rx23_fecl3_h2s", "sk": "reducers_nav29", "ref": "06.6", "n": 29, "lvl": 2, "l": ["FeCl3", "H2S"], "r": ["FeCl2", "S", "HCl"], "c": [2, 1, 2, 1, 2], "ox": 0, "red": 1, "if": "водный раствор (жёлтый осадок серы S↓)", "bad": [["Fe2S3", "В растворе Fe^{3+} окисляет H2S до серы S↓ вместо осаждения Fe2S3."], ["H2SO4", "Мягкий окислитель Fe^{3+} окисляет сероводород только до жёлтой серы S↓."]], "why": "Fe^{+3} + 1e⁻ → Fe^{+2} (×2), S^{−2} − 2e⁻ → S^{0} (×1). Выпадает жёлтый осадок серы S↓."}, {"id": "rx24_fecl3_na2so3_h2o", "sk": "reducers_nav29", "ref": "06.6", "n": 29, "lvl": 3, "l": ["FeCl3", "Na2SO3", "H2O"], "r": ["FeCl2", "Na2SO4", "HCl"], "c": [2, 1, 1, 2, 1, 2], "ox": 0, "red": 1, "if": "водный раствор (ОВР без осадка и газа, осветление раствора)", "bad": [["Fe(OH)3", "В отличие от Al^{3+} и Cr^{3+}, пара Fe^{3+} + SO3^{2−} вступает в ОВР, а не в совместный гидролиз."], ["SO2", "Сульфит окисляется до сульфата Na2SO4 без выделения газа."]], "why": "Fe^{+3} + 1e⁻ → Fe^{+2} (×2), S^{+4} − 2e⁻ → S^{+6} (×1). Важнейший прочерк таблицы растворимости — именно ОВР!"}, {"id": "rx25_nacl_melt", "sk": "melt_electrolysis", "ref": "07.11", "n": 20, "lvl": 1, "l": ["NaCl"], "r": ["Na", "Cl2"], "c": [2, 2, 1], "if": "расплав, электролиз (промышленное получение Na)", "bad": [["H2", "В расплаве нет воды, поэтому на катоде выделяется металлический натрий Na, а не H2."], ["NaOH", "Щёлочь образуется только при электролизе водного раствора NaCl."]], "why": "Катод: Na^{+} + e⁻ → Na (×2); Анод: 2Cl^{−} − 2e⁻ → Cl2↑."}, {"id": "rx26_kf_melt", "sk": "melt_electrolysis", "ref": "07.11", "n": 20, "lvl": 2, "l": ["KF"], "r": ["K", "F2"], "c": [2, 2, 1], "if": "расплав, электролиз (единственный способ получения F2)", "bad": [["O2", "В расплаве нет воды, поэтому на аноде окисляется сам F^{−} до фтора F2↑."], ["H2", "В расплаве на катоде выделяется металлический калий K."]], "why": "Катод: K^{+} + e⁻ → K (×2); Анод: 2F^{−} − 2e⁻ → F2↑. Из водного раствора KF фтор получить невозможно."}, {"id": "rx27_naoh_melt", "sk": "melt_electrolysis", "ref": "07.11", "n": 20, "lvl": 3, "l": ["NaOH"], "r": ["Na", "O2", "H2O"], "c": [4, 4, 1, 2], "if": "расплав, электролиз (на аноде O2↑ и пары H2O↑)", "bad": [["H2", "В расплаве щёлочи на катоде выделяется натрий Na, а OH^{−} окисляются на аноде до O2 и H2O."], ["Na2O", "Щёлочь при электролизе расплава даёт свободный металл Na, O2 и H2O."]], "why": "Катод: Na^{+} + e⁻ → Na (×4); Анод: 4OH^{−} − 4e⁻ → O2↑ + 2H2O↑."}, {"id": "rx28_al2o3_melt", "sk": "melt_electrolysis", "ref": "07.11", "n": 20, "lvl": 2, "l": ["Al2O3"], "r": ["Al", "O2"], "c": [2, 4, 3], "if": "расплав в криолите Na3AlF6, электролиз (получение Al)", "bad": [["F2", "Криолит служит лишь растворителем для снижения температуры плавления; разлагается Al2O3."], ["H2", "Воды в расплаве нет — на катоде выделяется жидкий алюминий Al."]], "why": "Катод: Al^{3+} + 3e⁻ → Al (×4); Анод: 2O^{2−} − 4e⁻ → O2↑ (×3)."}, {"id": "rx29_kolbe_ch3coona", "sk": "summary_electrolysis", "ref": "09.8", "n": 20, "lvl": 3, "l": ["CH3COONa", "H2O"], "r": ["C2H6", "CO2", "H2", "NaOH"], "c": [2, 2, 1, 2, 1, 2], "if": "водный раствор, электролиз (синтез Кольбе)", "bad": [["O2", "Ацетат-ионы окисляются на аноде вместо воды, давая этан C2H6↑ и CO2↑."], ["CH4", "При синтезе Кольбе радикалы удваиваются: два метила дают этан C2H6, а не метан."], ["Na", "Натрий стоит до Al — на катоде в водном растворе выделяется H2↑."]], "why": "Катод: 2H2O + 2e⁻ → H2↑ + 2OH^{−}; Анод: 2CH3COO^{−} − 2e⁻ → C2H6↑ + 2CO2↑. В растворе накапливается NaOH."}, {"id": "rx30_cuso4_sol", "sk": "summary_electrolysis", "ref": "09.8", "n": 20, "lvl": 2, "l": ["CuSO4", "H2O"], "r": ["Cu", "O2", "H2SO4"], "c": [2, 2, 2, 1, 2], "if": "водный раствор, инертные электроды, электролиз (pH падает)", "bad": [["H2", "Медь стоит после водорода — на катоде выделяется только Cu (пока соль не кончилась)."], ["SO2", "Сульфат-ион в воде не окисляется — на аноде окисляется вода до O2↑."]], "why": "Катод: Cu^{2+} + 2e⁻ → Cu (×2); Анод: 2H2O − 4e⁻ → O2↑ + 4H^{+}. В растворе накапливается серная кислота H2SO4."}, {"id": "rx31_kcl_sol", "sk": "summary_electrolysis", "ref": "09.8", "n": 20, "lvl": 2, "l": ["KCl", "H2O"], "r": ["H2", "Cl2", "KOH"], "c": [2, 2, 1, 1, 2], "if": "водный раствор, инертные электроды, электролиз (pH растёт)", "bad": [["K", "Калий стоит до Al — в водном растворе на катоде выделяется H2↑."], ["O2", "Бескислородный Cl^{−} окисляется на аноде сам до Cl2↑."]], "why": "Катод: 2H2O + 2e⁻ → H2↑ + 2OH^{−}; Анод: 2Cl^{−} − 2e⁻ → Cl2↑. В растворе накапливается щёлочь KOH."}, {"id": "rx32_nah_melt", "sk": "melt_electrolysis", "ref": "07.10", "n": 20, "lvl": 3, "l": ["NaH"], "r": ["Na", "H2"], "c": [2, 2, 1], "if": "расплав, электролиз (H2↑ выделяется на АНОДЕ!)", "bad": [["NaOH", "В расплаве гидрида нет воды и кислорода."], ["O2", "В составе NaH нет кислорода — на аноде окисляется H^{−} до H2↑."]], "why": "Катод: Na^{+} + e⁻ → Na (×2); Анод: 2H^{−} − 2e⁻ → H2↑. Уникальный случай выделения водорода на аноде!"}, {"id": "rx33_cucl2_sol", "sk": "summary_electrolysis", "ref": "09.4", "n": 20, "lvl": 1, "l": ["CuCl2"], "r": ["Cu", "Cl2"], "c": [1, 1, 1], "if": "водный раствор, инертные электроды, электролиз (вода не участвует)", "bad": [["H2", "Cu^{2+} стоит после H2 — на катоде только Cu."], ["O2", "Cl^{−} — бескислородный анион, окисляется сам до Cl2↑."]], "why": "Неактивный металл + бескислородный анион (не F^{−}): разряжаются оба иона соли, вода не участвует."}, {"id": "rx34_h2o_electrolysis", "sk": "summary_electrolysis", "ref": "09.4", "n": 20, "lvl": 1, "l": ["H2O"], "r": ["H2", "O2"], "c": [2, 2, 1], "if": "водный раствор Na2SO4 / KNO3 / NaF / NaOH / H2SO4, электролиз", "bad": [["H2O2", "При электролизе воды образуются простые вещества H2↑ (катод) и O2↑ (анод)."], ["Na", "Ионы активного металла и оксоанион/F^{−} остаются в растворе."]], "why": "Активный металл + оксоанион или F^{−} (а также щёлочи и оксокислоты) сводятся к электролизу воды."}, {"id": "rx35_h2o2_na2so3", "sk": "reducers_nav29", "ref": "06.9", "n": 29, "lvl": 2, "l": ["H2O2", "Na2SO3"], "r": ["Na2SO4", "H2O"], "c": [1, 1, 1, 1], "ox": 0, "red": 1, "if": "водный раствор (эталон признака «без видимых признаков»)", "bad": [["O2", "С восстановителем Na2SO3 пероксид работает как окислитель (O^{−1} → O^{−2}) без выделения O2."], ["SO2", "Сульфит окисляется пероксидом до сульфата Na2SO4."]], "why": "Все реагенты и продукты бесцветны и растворимы, газа и осадка нет — классика фильтра «без видимых признаков»."}], "seq": [{"id": "seq_balance_steps", "sk": "balance_fipi", "ref": "03.4", "n": 29, "lvl": 2, "q": "Выстрой в правильном порядке 5 шагов метода электронного баланса для задания № 29:", "items": ["Расставить степени окисления и выделить элементы, у которых СО изменилась", "Записать полусхемы окисления и восстановления с учётом удвоения (Cl2, I2, O2) или двойного окисления", "Найти НОК числа электронов и получить наименьшие целые множители", "Перенести коэффициенты в уравнение и уравнять катионы, среду и водород", "Проверить правильность коэффициентов обратным подсчётом атомов кислорода слева и справа"], "why": "Проверка по кислороду в самом конце — главный детектор любой арифметической ошибки в коэффициентах."}, {"id": "seq_nav29_steps", "sk": "reducers_nav29", "ref": "06.11", "n": 29, "lvl": 3, "q": "Расположи в правильном порядке 5 шагов алгоритма отбора пары для задания № 29 из перечня 6 веществ:", "items": ["Распределить все 6 веществ перечня по ролям: окислитель (О), восстановитель (В), среда (С)", "Отсечь реакции без смены СО (совместный гидролиз, переход CrO4^{2−} ⇄ Cr2O7^{2−})", "Выбрать среду и пару реагентов строго по всем словам фильтра условия (цвет, осадок, газ, число солей)", "Составить уравнение реакции и электронный баланс с указанием окислителя и восстановителя из левой части", "Проверить баланс по кислороду и убедиться, что записана ровно одна реакция с наименьшими целыми коэффициентами"], "why": "Такой порядок защищает от всех главных причин 0 баллов в № 29."}, {"id": "seq_electrolysis_cu", "sk": "summary_electrolysis", "ref": "09.10", "n": 20, "lvl": 3, "q": "Выстрой в хронологическом порядке события при длительном (последовательном) электролизе водного раствора CuSO4 на инертных электродах:", "items": ["Начинается этап 1: на катоде оседает медь Cu, на аноде выделяется O2↑", "Синяя окраска раствора постепенно бледнеет, а в растворе накапливается серная кислота H2SO4 (pH падает)", "Вся соль CuSO4 полностью расходуется (n(Cu^{2+}) = 0)", "Начинается этап 2: ток продолжает идти, и на катоде начинает выделяться водород H2↑ (электролиз воды)"], "why": "Появление водорода на катоде — точный сигнал перехода ко второму этапу электролиза после полного расходования соли меди."}], "facts": [{"id": "f_ox_basics", "sk": "ox_state", "ref": "01.5", "n": 19, "lvl": 2, "t": "Степени окисления и стандарт записи ФИПИ", "s": [["В фториде кислорода OF2 степень окисления кислорода равна +2.", "В фториде кислорода OF2 степень окисления кислорода равна −2.", "Фтор более электроотрицателен, чем кислород, поэтому у F всегда −1, а у O в OF2 равно +2."], ["В гидриде кальция CaH2 степень окисления водорода равна −1.", "В гидриде кальция CaH2 степень окисления водорода равна +1.", "В гидридах металлов водород забирает электроны у металла и имеет СО −1."], ["В пирите FeS2 степень окисления железа равна +2, а серы −1.", "В пирите FeS2 степень окисления железа равна +4, а серы −2.", "Пирит содержит дисульфид-ион S2^{2−} со связью S–S: (+2) + 2·(−1) = 0."], ["В уксусной кислоте CH3COOH атомы углерода имеют разные степени окисления: −3 и +3.", "В уксусной кислоте CH3COOH оба атома углерода имеют степень окисления 0.", "В группе −CH3 углерод имеет СО −3, а в карбоксильной группе −COOH — СО +3."], ["В электронном балансе ЕГЭ степень окисления пишется знаком вперёд (Mn^{+7}), а заряд иона — цифрой вперёд (Mn^{2+}).", "В электронном балансе ЕГЭ степень окисления нужно писать цифрой вперёд (Mn^{7+}), как заряд иона.", "Эксперты ФИПИ строго различают формат степени окисления (+7) и заряда иона (2+)."]]}, {"id": "f_kim19", "sk": "kim19_traps", "ref": "02.9", "n": 19, "lvl": 3, "t": "Ловушки задания № 19 (элемент vs вещество и органика)", "s": [["В реакции 2F2 + 2H2O → 4HF + O2↑ вода выступает в роли восстановителя.", "Вода H2O никогда не может быть восстановителем в ОВР.", "Фтор сильнее кислорода и окисляет O^{−2} воды до O2^{0}."], ["При гидрировании этилена (C2H4 + H2 → C2H6) этилен является окислителем, а водород — восстановителем.", "При гидрировании этилена (C2H4 + H2 → C2H6) этилен является восстановителем.", "Углерод понижает СО с −2 до −3 (принимает электроны → окислитель)."], ["Обжиг пирита 4FeS2 + 11O2 → 2Fe2O3 + 8SO2↑ не является реакцией диспропорционирования.", "Обжиг пирита 4FeS2 + 11O2 → 2Fe2O3 + 8SO2↑ является реакцией диспропорционирования.", "В пирите окисляются два разных элемента (Fe и S), а восстанавливается третий (O2) — это межмолекулярная ОВР."], ["В реакции NH4NO3 —t°→ N2O↑ + 2H2O азот выступает и окислителем, и восстановителем.", "В реакции NH4NO3 —t°→ N2O↑ + 2H2O азот является только окислителем.", "N^{−3} повышает СО до +1, а N^{+5} понижает СО до +1 — внутримолекулярное сопропорционирование."], ["В задании № 19 на соответствие цифры в ответе могут повторяться.", "В задании № 19 на соответствие все цифры в ответе обязаны быть разными.", "В таблице соответствия № 19 вполне может быть ответ вроде 334 или 112."]]}, {"id": "f_balance_ph", "sk": "ph_mn_cr", "ref": "04.4", "n": 29, "lvl": 3, "t": "Среды, KMnO4, хром и критерии № 29", "s": [["HCl нельзя брать как инертную кислую среду для KMnO4 и K2Cr2O7, так как Cl^{−} сам окисляется до Cl2↑.", "HCl — идеальная инертная кислая среда для реакций с KMnO4.", "Для инертной кислой среды берут H2SO4(разб.) или гидросульфаты KHSO4, NaHSO4, NH4HSO4."], ["Переход оранжевого K2Cr2O7 в жёлтый K2CrO4 в щёлочи не является ОВР.", "Переход K2Cr2O7 в K2CrO4 в щёлочи — это ОВР восстановления хрома.", "Степень окисления хрома в обоих анионах равна +6."], ["Окисление соединений Cr^{+3} до жёлтого хромата CrO4^{2−} в растворе проводят в щелочной среде.", "Соли Cr^{3+} окисляются пероксидом водорода до K2Cr2O7 в сернокислой среде.", "В кислой среде реакция идёт в обратную сторону: дихромат окисляет H2O2 до O2↑."], ["В № 29 дробные коэффициенты и запись двух разных уравнений «на всякий случай» не засчитываются.", "В № 29 можно записать два уравнения ОВР на выбор — эксперт выберет лучшее.", "В условии прямо сказано «только одной возможной ОВР», а коэффициенты должны быть целыми."], ["В Демоверсии-2027 замена H2SO4 на NH4HSO4 в реакции K2Cr2O7 + KI даёт третью соль (NH4)2SO4 и нарушает условие «раствор двух солей».", "В Демоверсии-2027 среда NH4HSO4 даёт ровно две соли, как и H2SO4.", "Лишний катион NH4^{+} образует третью соль (NH4)2SO4."]]}, {"id": "f_acids_red", "sk": "acids_h2o2_hal", "ref": "05.6", "n": 29, "lvl": 3, "t": "Кислоты-окислители, H2O2 и граница ОВР/РИО", "s": [["Холодные концентрированные HNO3 и H2SO4 пассивируют Fe, Al и Cr.", "Железо бурно растворяется в холодной концентрированной HNO3 с выделением H2↑.", "На поверхности Fe, Al, Cr образуется защитная оксидная плёнка; реакция идёт только при нагревании (до +3, без H2)."], ["С твёрдым NaCl концентрированная H2SO4 вступает в реакцию обмена (HCl↑), а с NaBr и NaI — в ОВР.", "С твёрдым NaCl концентрированная H2SO4 вступает в ОВР с выделением Cl2↑.", "Хлорид-ион не окисляется серной кислотой, в отличие от Br^{−} (Br2 + SO2↑) и I^{−} (I2 + H2S↑)."], ["Если в реакции с H2O2 выделяется газ O2↑, то пероксид водорода выступает восстановителем.", "Если в реакции с H2O2 выделяется газ O2↑, то пероксид водорода выступает окислителем.", "Переход O^{−1} → O2^{0} — отдача электронов (окисление восстановителя H2O2)."], ["Пары Fe^{3+} + I^{−}/S^{2−}/SO3^{2−} и Cu^{2+} + I^{−} — это ОВР (№ 29), а Al^{3+} + CO3^{2−}/S^{2−} — совместный гидролиз (№ 30).", "Все прочерки в таблице растворимости ФИПИ относятся только к реакциям совместного гидролиза (№ 30).", "Катионы Fe^{3+} и Cu^{2+} проявляют окислительные свойства к сильным восстановителям."], ["Вещества из перечня № 29 разрешено повторно использовать в задании № 30.", "Вещества, выбранные в № 29, запрещено использовать в № 30.", "Никакого запрета на повторное использование веществ между № 29 и № 30 в КИМ нет."]]}, {"id": "f_elec_melts", "sk": "melt_electrolysis", "ref": "07.12", "n": 20, "lvl": 2, "t": "Физика электролиза и электролиз расплавов", "s": [["Для проведения электролиза обязателен постоянный электрический ток.", "Электролиз одинаково успешно идёт при постоянном и переменном токе.", "При переменном токе электроды меняют полярность 50 раз в секунду, и разделения продуктов нет."], ["При электролизе на катоде (–) всегда идёт восстановление, а на аноде (+) — окисление.", "При электролизе на катоде идёт окисление, а на аноде — восстановление.", "Катод (–) отдаёт электроны катионам (восстановление), анод (+) забирает электроны у анионов (окисление)."], ["Алюминий в промышленности получают электролизом раствора Al2O3 в расплаве криолита Na3AlF6, а не из расплава AlCl3.", "Алюминий в промышленности получают электролизом расплава безводного хлорида AlCl3.", "Безводный AlCl3 имеет молекулярную решётку, возгоняется и не проводит ток в расплаве."], ["При электролизе расплава гидрида натрия NaH водород H2↑ выделяется на аноде (+).", "При электролизе расплава NaH водород H2↑ выделяется на катоде (–).", "В NaH водород — анион H^{−}, который окисляется на положительном аноде."], ["В расплаве щёлочи NaOH на катоде выделяется металлический натрий, а на аноде — O2↑ и пары H2O↑.", "В расплаве щёлочи NaOH на катоде выделяется водород H2↑.", "В расплаве нет свободной воды — катион Na^{+} восстанавливается сам до металла Na."]]}, {"id": "f_elec_solutions", "sk": "solution_rules", "ref": "08.12", "n": 20, "lvl": 3, "t": "Ловушки электролиза водных растворов (№ 20)", "s": [["При электролизе водного раствора любого фторида (NaF, KF, CuF2, HF) на аноде выделяется O2↑, а не F2.", "При электролизе водного раствора NaF на аноде выделяется фтор F2↑.", "Фтор — самый электроотрицательный элемент, в воде вместо F^{−} окисляется вода до O2↑."], ["При электролизе водного раствора Pb(NO3)2 на катоде выделяются свинец и водород.", "При электролизе водного раствора Pb(NO3)2 на катоде выделяется только свинец без водорода.", "Свинец Pb стоит ДО (H2) в ряду напряжений ФИПИ (средняя зона Mn–Pb → металл и H2)."], ["При электролизе водного раствора NH4Cl на катоде выделяется водород H2↑.", "При электролизе водного раствора NH4Cl на катоде выделяется свободный азот N2↑.", "Ион аммония NH4^{+} в № 20 ведёт себя как активный металл — главный продукт на катоде H2↑."], ["При электролизе водного раствора ацетата калия CH3COOK на аноде выделяются этан C2H6↑ и CO2↑.", "При электролизе водного раствора CH3COOK на аноде выделяется кислород O2↑.", "Карбоксилат-ионы вступают в синтез Кольбе: 2CH3COO^{−} − 2e⁻ → C2H6↑ + 2CO2↑."], ["При электролизе водного раствора CuSO4 с медным (активным) анодом на аноде не выделяется O2↑ — растворяется сама медь.", "При электролизе раствора CuSO4 с медным анодом на аноде выделяется кислород O2↑.", "Активный металл анода окисляется легче воды: Cu − 2e⁻ → Cu^{2+}."]]}, {"id": "f_kim20_industry", "sk": "kim20_industry", "ref": "10.7", "n": 20, "lvl": 3, "t": "Промышленное получение веществ и ловушки № 20", "s": [["Для получения Cl2, H2 и NaOH в промышленности проводят электролиз водного раствора NaCl.", "Для получения NaOH в промышленности проводят электролиз расплава NaCl.", "Из расплава NaCl получаются только Na и Cl2 (без H2 и без NaOH)."], ["Натрий, калий, кальций и магний нельзя получить электролизом водных растворов их солей.", "Калий и магний в промышленности получают электролизом водных растворов их хлоридов.", "Все металлы от Li до Al в воде уступают на катоде молекулам воды (выделяется H2↑)."], ["В водных растворах Na2SO4, KNO3, NaOH и H2SO4 при электролизе разлагается только вода, а массовая доля электролита растёт.", "При электролизе водного раствора Na2SO4 масса соли в растворе быстро уменьшается.", "На катоде идёт H2↑, на аноде O2↑; сама соль служит лишь проводником тока."], ["В задании № 20 за одну неверную цифру из трёх ставят 0 баллов (максимум 1 балл).", "В задании № 20 за одну ошибку из трёх ставят 1 балл из 2.", "№ 20 — задание базового уровня стоимостью 1 балл: для балла нужны все 3 верные цифры."], ["Медь Cu, серебро Ag и ртуть Hg стоят после (H2) в ряду ФИПИ, поэтому из водных растворов их солей на катоде выделяется только металл.", "Ртуть Hg стоит до водорода и выделяется из раствора вместе с водородом.", "В ряду ФИПИ порядок: ... Pb (H2) Cu Hg Ag Pt Au."]]}], "calc": [{"id": "c_ox_anion", "sk": "ox_state", "ref": "01.5", "n": 19, "lvl": 1, "v": {"_": [{"k": 1, "o": 4, "q": 1}, {"k": 1, "o": 4, "q": 2}, {"k": 2, "o": 7, "q": 2}, {"k": 1, "o": 3, "q": 1}, {"k": 1, "o": 2, "q": 1}, {"k": 2, "o": 4, "q": 2}]}, "q": "В сложном оксоанионе элемент X встречается {=k} раз(а), кислород O^{−2} — {=o} раз(а), а отрицательный заряд аниона равен {=q}−. Чему равна положительная степень окисления элемента X? Введите целое число.", "a": "(2 * o - q) / k", "dp": 0, "unit": "", "ex": "{=k}·x + {=o}·(−2) = −{=q} → {=k}·x = {=2*o - q} → x = +{(2*o - q)/k}."}, {"id": "c_balance_e", "sk": "balance_fipi", "ref": "03.4", "n": 29, "lvl": 2, "v": {"_": [{"a": 7, "b": 2, "m": 1}, {"a": 7, "b": 4, "m": 1}, {"a": 6, "b": 3, "m": 2}, {"a": 5, "b": 2, "m": 1}, {"a": 5, "b": -3, "m": 1}, {"a": 5, "b": -1, "m": 1}]}, "q": "В полусхеме восстановления участвуют {=m} атом(а) элемента, степень окисления каждого понижается с +{=a} до {=b}. Сколько всего электронов принято в этой полусхеме?", "a": "m * (a - b)", "dp": 0, "unit": "e⁻", "ex": "Один атом принимает ({=a}) − ({=b}) = {=a-b} e⁻; на {=m} атом(а) приходится {=m*(a-b)} e⁻."}, {"id": "c_double_ox", "sk": "balance_fipi", "ref": "03.8", "n": 29, "lvl": 3, "v": {"_": [{"e1": 1, "n2": 2, "e2": 5}, {"e1": 2, "n2": 1, "e2": 8}, {"e1": 1, "n2": 2, "e2": 7}, {"e1": 3, "n2": 3, "e2": 8}]}, "q": "При двойном окислении 1 формульной единицы бинарного соединения первый элемент суммарно отдаёт {=e1} e⁻, а второй элемент (индекс {=n2}) отдаёт по {=e2} e⁻ от каждого атома. Сколько всего электронов отдаёт 1 формульная единица восстановителя?", "a": "e1 + n2 * e2", "dp": 0, "unit": "e⁻", "ex": "Суммарная отдача равна {=e1} + {=n2} · {=e2} = {=e1 + n2*e2} e⁻ (так считают баланс для FeS2, Cu2S, CrI3)."}], "tasks": [{"id": "t01_kim19_match_n", "type": "match", "sk": "kim19_traps", "ref": "02.12", "n": 19, "lvl": 2, "q": "Установите соответствие между уравнением реакции и свойством, которое проявляет АЗОТ в этой реакции.", "left": ["NH4NO3 —t°→ N2O↑ + 2H2O", "2NO2 + 2NaOH → NaNO2 + NaNO3 + H2O", "NH4Cl + NaOH —t°→ NaCl + NH3↑ + H2O"], "right": ["Только окислитель", "Только восстановитель", "И окислитель, и восстановитель", "Не проявляет ОВ-свойств"], "a": [2, 2, 3], "ex": "В А (N^{−3} и N^{+5} → N^{+1}) и Б (N^{+4} → N^{+3} и N^{+5}) азот и окислитель, и восстановитель (3); в В везде N^{−3} — не ОВР (4). Ответ: 334 (цифры могут повторяться!)."}, {"id": "t02_kim19_multi_only_red", "type": "multi", "sk": "ox_state", "ref": "01.13", "n": 19, "lvl": 2, "q": "Выберите два вещества, в которых указанный в скобках элемент может проявлять ТОЛЬКО восстановительные свойства.", "o": ["NH3 (азот)", "Na2SO3 (сера)", "KI (иод)", "K2Cr2O7 (хром)", "KNO2 (азот)"], "a": [0, 2], "ex": "В NH3 у азота минимальная СО −3, в KI у иода минимальная СО −1 — они могут только отдавать электроны. S^{+4} и N^{+3} двойственны, Cr^{+6} — только окислитель."}, {"id": "t03_kim19_multi_no_ovr", "type": "multi", "sk": "kim19_traps", "ref": "02.9", "n": 19, "lvl": 3, "q": "Из предложенного перечня выберите две реакции, которые НЕ являются окислительно-восстановительными.", "o": ["K2Cr2O7 + 2KOH → 2K2CrO4 + H2O", "CH2=CH2 + H2 —t°, Ni→ CH3–CH3", "CH2=CH2 + H2O —H^{+}→ CH3–CH2OH", "2F2 + 2H2O → 4HF + O2↑", "2H2O2 —MnO2→ 2H2O + O2↑"], "a": [0, 2], "ex": "В (1) везде Cr^{+6}, в (3) гидратация алкена без смены суммарных степеней окисления (не-ОВР). В (2), (4) и (5) степени окисления меняются."}, {"id": "t04_kim19_match_h2o2", "type": "match", "sk": "acids_h2o2_hal", "ref": "05.10", "n": 19, "lvl": 3, "q": "Установите соответствие между схемой реакции и ролью пероксида водорода H2O2 в этой реакции.", "left": ["KMnO4 + H2O2 + H2SO4 → MnSO4 + O2↑ + K2SO4 + H2O", "KI + H2O2 + H2SO4 → I2↓ + K2SO4 + H2O", "H2O2 —MnO2→ H2O + O2↑"], "right": ["Только окислитель", "Только восстановитель", "И окислитель, и восстановитель", "Не проявляет ОВ-свойств"], "a": [1, 0, 2], "ex": "С KMnO4 кислород O^{−1} → O2^{0} (восстановитель); с KI кислород O^{−1} → O^{−2} (окислитель); при разложении H2O2 диспропорционирует (и ОК, и ВС)."}, {"id": "t05_num_cr_mol", "type": "num", "sk": "kim19_traps", "ref": "02.3", "n": 19, "lvl": 3, "q": "Сколько моль электронов принимает 1 моль дихромата калия K2Cr2O7 при полном восстановлении в кислой среде до Cr2(SO4)3? Введите целое число.", "a": 6, "ex": "Один атом Cr^{+6} принимает 3e⁻ (до Cr^{+3}), но в 1 моль K2Cr2O7 содержится 2 моль атомов хрома: 2 · 3 = 6 моль электронов."}, {"id": "t06_num_fes2_o2_coef", "type": "num", "sk": "balance_fipi", "ref": "03.9", "n": 29, "lvl": 3, "q": "Укажи коэффициент перед кислородом O2 в сбалансированном уравнении обжига пирита: ?FeS2 + ?O2 —t°→ ?Fe2O3 + ?SO2↑. Введите целое число.", "a": 11, "ex": "Баланс: FeS2 отдаёт 11e⁻ (Fe^{+2}→Fe^{+3} и 2S^{−1}→2S^{+4}), O2 принимает 4e⁻ → 4FeS2 + 11O2 → 2Fe2O3 + 8SO2↑. Коэффициент перед O2 равен 11."}, {"id": "t07_eqn_active_anode", "type": "eqn", "sk": "summary_electrolysis", "ref": "09.14", "n": 20, "lvl": 3, "q": "Запиши анодную полуреакцию растворения активного медного анода при электролитическом рафинировании меди (используй символы e⁻ и Cu^{2+}).", "a": "Cu − 2e⁻ → Cu^{2+}", "ex": "На активном (растворимом) медном аноде окисляются атомы самого металла анода: Cu − 2e⁻ → Cu^{2+}."}, {"id": "t08_kim20_match_proto1", "type": "match", "sk": "kim20_industry", "ref": "10.9", "n": 20, "lvl": 2, "q": "Установите соответствие между формулой соли и продуктами электролиза её ВОДНОГО РАСТВОРА на инертных электродах.", "left": ["AgNO3", "NaF", "ZnCl2"], "right": ["Металл и кислород", "Водород и кислород", "Водород и фтор", "Металл, водород и хлор", "Металл и хлор"], "a": [0, 1, 3], "ex": "AgNO3 → Ag и O2 (1); NaF → H2 и O2 (2, ловушка — F2 не выделяется!); ZnCl2 → Zn, H2 и Cl2 (4, Zn между Al и H2!). Ответ: 124."}, {"id": "t09_kim20_match_proto2", "type": "match", "sk": "kim20_industry", "ref": "10.9", "n": 20, "lvl": 3, "q": "Установите соответствие между простым веществом и промышленным способом его получения электролизом.", "left": ["Калий (K)", "Алюминий (Al)", "Фтор (F2)"], "right": ["Электролиз водного раствора KF", "Электролиз расплава KCl", "Электролиз расплава NaF", "Электролиз раствора Al2O3 в расплаве криолита", "Электролиз водного раствора Al2(SO4)3"], "a": [1, 3, 2], "ex": "Калий — только расплав соли калия KCl (2); алюминий — Al2O3 в расплаве криолита (4); фтор — только расплав фторида NaF (3, из водного KF выделится O2!). Ответ: 243."}, {"id": "t10_kim20_match_cathode", "type": "match", "sk": "solution_rules", "ref": "08.14", "n": 20, "lvl": 3, "q": "Установите соответствие между формулой соли и продуктом электролиза её ВОДНОГО РАСТВОРА на инертном КАТОДЕ (–).", "left": ["NH4NO3", "Pb(NO3)2", "Hg(NO3)2"], "right": ["Только водород", "Только металл", "Металл и водород", "Азот и водород"], "a": [0, 2, 1], "ex": "NH4^{+} → только H2 (1); Pb стоит ДО (H2) → Pb и H2 (3); Hg стоит ПОСЛЕ (H2) → только Hg (2). Ответ: 132."}, {"id": "t11_kim20_match_anode", "type": "match", "sk": "solution_rules", "ref": "08.14", "n": 20, "lvl": 3, "q": "Установите соответствие между формулой соли и продуктом электролиза её ВОДНОГО РАСТВОРА на инертном АНОДЕ (+).", "left": ["CuF2", "CH3COOK", "FeBr2"], "right": ["Кислород", "Фтор", "Этан и углекислый газ", "Бром"], "a": [0, 2, 3], "ex": "F^{−} в воде не окисляется → O2 (1); ацетат CH3COOK → синтез Кольбе: C2H6 и CO2 (3); бескислородный Br^{−} → Br2 (4). Ответ: 134."}, {"id": "t12_kim20_multi_water_only", "type": "multi", "sk": "summary_electrolysis", "ref": "09.5", "n": 20, "lvl": 2, "q": "Выберите два вещества, электролиз ВОДНЫХ РАСТВОРОВ которых на инертных электродах фактически сводится к электролизу воды (2H2O → 2H2↑ + O2↑).", "o": ["Na2SO4", "CuSO4", "KCl", "KF", "AgNO3"], "a": [0, 3], "ex": "В Na2SO4 и KF на катоде выделяется H2↑ (активные металлы до Al), а на аноде — O2↑ (оксоанион и фторид в воде не окисляются). Итог — электролиз воды."}, {"id": "t13_kim20_one_melt_vs_sol", "type": "one", "sk": "melt_electrolysis", "ref": "07.13", "n": 20, "lvl": 2, "q": "В каком случае на катоде выделяется металлический натрий Na, а на аноде — кислород O2↑ и пары воды H2O↑?", "o": ["Электролиз расплава NaOH", "Электролиз водного раствора NaOH", "Электролиз расплава NaCl", "Электролиз водного раствора Na2SO4"], "a": 0, "ex": "4NaOH(расплав) —электролиз→ 4Na + O2↑ + 2H2O↑. В водном растворе NaOH на катоде выделяется H2↑, а не Na.", "d": {"1": "В водном растворе NaOH идёт электролиз воды (H2↑ и O2↑), натрий не выделяется.", "2": "Из расплава NaCl на аноде выделяется хлор Cl2↑, а не O2↑.", "3": "В водном растворе Na2SO4 выделяются H2↑ и O2↑."}}, {"id": "t14_kim29_one_rio_trap", "type": "one", "sk": "reducers_nav29", "ref": "06.7", "n": 29, "lvl": 3, "q": "В перечне веществ для № 29–30 даны: AlCl3, Na2CO3, FeCl3, KI, Ba(NO3)2, H2O. Какую реакцию НЕЛЬЗЯ записывать в задание № 29?", "o": ["2AlCl3 + 3Na2CO3 + 3H2O → 2Al(OH)3↓ + 3CO2↑ + 6NaCl", "2FeCl3 + 2KI → 2FeCl2 + I2↓ + 2KCl", "Обе реакции подходят для № 29", "Ни одна из реакций не идёт"], "a": 0, "ex": "Реакция AlCl3 с Na2CO3 — совместный гидролиз (степени окисления не меняются!), она относится строго к заданию № 30. В № 29 идёт ОВР: 2FeCl3 + 2KI → 2FeCl2 + I2↓ + 2KCl.", "d": {"1": "Это реальная ОВР (Fe^{+3} → Fe^{+2}, I^{−1} → I2^{0}) — она подходит для № 29.", "2": "Первая реакция — не ОВР.", "3": "Обе реакции протекают, но относятся к разным заданиям КИМ."}}, {"id": "t15_part2_demo2027", "type": "part2", "sk": "ph_mn_cr", "ref": "04.18", "n": 29, "lvl": 3, "max": 2, "q": "[ДЕМО-2027 ФИПИ] Перечень веществ: нитрит калия (KNO2), сульфит калия (K2SO3), дихромат калия (K2Cr2O7), серная кислота (H2SO4), иодид калия (KI), гидросульфат аммония (NH4HSO4). Допустимо использование водных растворов веществ. Выберите окислитель и восстановитель, реакция между которыми в соответствующей среде протекает с образованием простого вещества и раствора двух солей. Запишите уравнение реакции, составьте электронный баланс, укажите окислитель и восстановитель.", "ideal": "K2Cr2O7 + 6KI + 7H2SO4 → 3I2↓ + Cr2(SO4)3 + 4K2SO4 + 7H2O\n\nЭлектронный баланс:\n2Cr^{+6} + 6e⁻ → 2Cr^{+3} | 1 (восстановление)\n2I^{−1} − 2e⁻ → I2^{0} | 3 (окисление)\n\nK2Cr2O7 (за счёт Cr^{+6}) — окислитель; KI (за счёт I^{−1}) — восстановитель.\n(Среда H2SO4 даёт ровно 2 соли; NH4HSO4 дал бы 3 соли.)", "crit": [["Верно выбраны вещества и записано сбалансированное уравнение K2Cr2O7 + 6KI + 7H2SO4 → 3I2 + Cr2(SO4)3 + 4K2SO4 + 7H2O", 1], ["Верно составлен электронный баланс (множители 1 и 3) и указаны окислитель (K2Cr2O7 / Cr^{+6}) и восстановитель (KI / I^{−1})", 1]], "ex": "Эталон Демоверсии ЕГЭ-2027. Проверка O: 7 + 28 = 35 и 12 + 16 + 7 = 35."}, {"id": "t16_part2_kmno4_decolor", "type": "part2", "sk": "reducers_nav29", "ref": "06.11", "n": 29, "lvl": 3, "max": 2, "q": "Перечень веществ: перманганат калия (KMnO4), сульфит натрия (Na2SO3), иодид калия (KI), серная кислота (H2SO4), гидроксид бария (Ba(OH)2), сульфат железа(II) (FeSO4). Выберите вещества, ОВР между которыми приводит к обесцвечиванию раствора без образования осадка и выделения газа. Запишите уравнение, составьте электронный баланс, укажите окислитель и восстановитель.", "ideal": "2KMnO4 + 5Na2SO3 + 3H2SO4 → 2MnSO4 + 5Na2SO4 + K2SO4 + 3H2O\n\nЭлектронный баланс:\nMn^{+7} + 5e⁻ → Mn^{+2} | 2 (восстановление)\nS^{+4} − 2e⁻ → S^{+6} | 5 (окисление)\n\nKMnO4 (за счёт Mn^{+7}) — окислитель; Na2SO3 (за счёт S^{+4}) — восстановитель.", "crit": [["Выбрана пара KMnO4 + Na2SO3 в среде H2SO4 и записано сбалансированное уравнение (KI даёт осадок I2, FeSO4 — жёлтый раствор)", 1], ["Верно составлен электронный баланс (множители 2 и 5) и указаны окислитель и восстановитель из левой части", 1]], "ex": "Проверка O: 8 + 15 + 12 = 35 и 8 + 20 + 4 + 3 = 35."}, {"id": "t17_part2_cu2s_hno3", "type": "part2", "sk": "acids_h2o2_hal", "ref": "05.4", "n": 29, "lvl": 3, "max": 2, "q": "Перечень веществ: сульфид меди(I) (Cu2S), концентрированная азотная кислота (HNO3), хлорид натрия (NaCl), сульфат калия (K2SO4), хлорид бария (BaCl2), гидроксид калия (KOH). Выберите вещества, при взаимодействии которых чёрное твёрдое вещество растворяется с выделением бурого газа и образованием раствора двух солей. Запишите уравнение, электронный баланс, укажите окислитель и восстановитель.", "ideal": "Cu2S + 12HNO3(конц.) → Cu(NO3)2 + CuSO4 + 10NO2↑ + 6H2O\n\nЭлектронный баланс:\n2Cu^{+1} + S^{−2} − 10e⁻ → 2Cu^{+2} + S^{+6} | 1 (окисление)\nN^{+5} + 1e⁻ → N^{+4} | 10 (восстановление)\n\nHNO3 (за счёт N^{+5}) — окислитель; Cu2S (за счёт Cu^{+1} и S^{−2}) — восстановитель.", "crit": [["Записано сбалансированное уравнение Cu2S + 12HNO3 → Cu(NO3)2 + CuSO4 + 10NO2 + 6H2O (две соли и бурый газ)", 1], ["Верно составлен суммарный баланс двойного окисления (множители 1 и 10) и указаны окислитель и восстановитель", 1]], "ex": "Проверка O: 36 = 6 + 4 + 20 + 6."}, {"id": "t18_part2_zn_nano3_naoh", "type": "part2", "sk": "acids_h2o2_hal", "ref": "05.7", "n": 29, "lvl": 3, "max": 2, "q": "Перечень веществ: цинк (Zn), нитрат натрия (NaNO3), гидроксид натрия (NaOH), сульфат калия (K2SO4), хлорид бария (BaCl2), оксид меди(II) (CuO). Выберите вещества, при нагревании которых в водном растворе выделяется газ с резким запахом и образуется комплексная соль. Запишите уравнение, электронный баланс, укажите окислитель и восстановитель.", "ideal": "4Zn + NaNO3 + 7NaOH + 6H2O —t°→ 4Na2[Zn(OH)4] + NH3↑\n\nЭлектронный баланс:\nZn^{0} − 2e⁻ → Zn^{+2} | 4 (окисление)\nN^{+5} + 8e⁻ → N^{−3} | 1 (восстановление)\n\nNaNO3 (за счёт N^{+5}) — окислитель; Zn (за счёт Zn^{0}) — восстановитель.", "crit": [["Записано сбалансированное уравнение 4Zn + NaNO3 + 7NaOH + 6H2O → 4Na2[Zn(OH)4] + NH3", 1], ["Верно составлен электронный баланс (множители 4 и 1) и указаны окислитель и восстановитель", 1]], "ex": "Проверка O: 3 + 7 + 6 = 16 и 4·4 = 16."}, {"id": "t19_part2_k3croh6_h2o2", "type": "part2", "sk": "ph_mn_cr", "ref": "04.16", "n": 29, "lvl": 3, "max": 2, "q": "Перечень веществ: гексагидроксохромат(III) калия (K3[Cr(OH)6]), пероксид водорода (H2O2), сульфат натрия (Na2SO4), хлорид бария (BaCl2), нитрат калия (KNO3), медь (Cu). Выберите два вещества, ОВР между которыми сопровождается переходом зелёной окраски раствора в жёлтую без выделения газа и выпадения осадка. Запишите уравнение, электронный баланс, укажите окислитель и восстановитель.", "ideal": "2K3[Cr(OH)6] + 3H2O2 → 2K2CrO4 + 2KOH + 8H2O\n\nЭлектронный баланс:\nCr^{+3} − 3e⁻ → Cr^{+6} | 2 (окисление)\n2O^{−1} + 2e⁻ → 2O^{−2} | 3 (восстановление)\n\nH2O2 (за счёт O^{−1}) — окислитель; K3[Cr(OH)6] (за счёт Cr^{+3}) — восстановитель.", "crit": [["Записано сбалансированное уравнение 2K3[Cr(OH)6] + 3H2O2 → 2K2CrO4 + 2KOH + 8H2O", 1], ["Верно составлен электронный баланс (множители 2 и 3) и указаны окислитель и восстановитель", 1]], "ex": "Проверка O: 12 + 6 = 18 и 8 + 2 + 8 = 18."}], "subjectSlug": "chemistry", "_kim": {"19": {"b": 1, "l": "Б"}, "20": {"b": 1, "l": "Б"}, "29": {"b": 2, "l": "В"}}, "_kon": {"01": {"t": "Модуль 01. Степень окисления, окислитель и восстановитель", "x": "Окислительно-восстановительная реакция (ОВР) — это реакция, в которой меняется [[Степень окисления|степень окисления]] хотя бы одного элемента. Атом, который принимает электроны и понижает СО, — [[Окислитель|окислитель]]; атом, который отдаёт электроны и повышает СО, — [[Восстановитель|восстановитель]]."}, "01.1": {"t": "Модуль 01 · Главная мысль.", "x": "Окислительно-восстановительная реакция (ОВР) — это реакция, в которой меняется [[Степень окисления|степень окисления]] хотя бы одного элемента. Атом, который принимает электроны и понижает СО, — [[Окислитель|окислитель]]; атом, который отдаёт электроны и повышает СО, — [[Восстановитель|восстановитель]]."}, "01.5": {"t": "Модуль 01 · 1. Как безошибочно считать степень окисления", "x": "• **Металлы IA, IIA, Al** — Обычная СО: +1, +2, +3; Исключения, на которых ловят в ЕГЭ: Нет (в соединениях всегда постоянна); Почему возникает исключение: Низкая ЭО: отдают все валентные электроны\n• **Фтор (F)** — Обычная СО: −1; Исключения, на которых ловят в ЕГЭ: Нет (в простом веществе F2 равна 0); Почему возникает исключение: Самый высокий показатель ЭО в ПСХЭ\n• **Кислород (O)** — Обычная СО: −2; Исключения, на которых ловят в ЕГЭ: OF2 (+2), O2F2 (+1), пероксиды H2O2/Na2O2/BaO2 (−1), надпероксид KO2 (−1/2); Почему возникает исключение: Фтор сильнее притягивает e⁻, а в пероксидах есть связь O–O, где электроны делятся поровну\n• **Водород (H)** — Обычная СО: +1; Исключения, на которых ловят в ЕГЭ: Гидриды металлов (NaH, CaH2, AlH3, LiAlH4): H^{−1}; Почему возникает исключение: ЭО водорода выше, чем у металлов, поэтому H забирает e⁻ у металла…"}, "01.7": {"t": "Модуль 01 · 2. Разбор сложных частиц: пирит, нитрат аммония и органика", "x": "**Шаг 1.** **Пероксид водорода (H2O2):** водород с неметаллом имеет СО +1. Два атома H дают +2, значит на два атома O приходится −2, то есть на один атом кислорода O^{−1} (из-за связи H–O–O–H).\n**Шаг 2.** **Гидрид кальция (CaH2):** кальций — металл IIA группы, его СО всегда +2. Чтобы сумма была 0, каждый водород имеет СО H^{−1}.\n**Шаг 3.** **Пирит (FeS2):** это не сульфид железа(IV)! В кристалле пирита содержится дисульфид-ион S2^{2−} со связью S–S, поэтому у железа Fe^{+2}, а у каждого атома серы S^{−1}.\n**Шаг 4.** **Нитрат аммония (NH4NO3):** два атома азота входят в разные частицы: в катионе NH4^{+} (единицу в заряде однозарядного иона не пишут!) степень окисления азота равна −3, а в анионе NO3^{−} степень окисления азота равна +5.…"}, "01.8": {"t": "Модуль 01 · Критичный стандарт записи ФИПИ ЕГЭ-2027", "x": "В заданиях части 2 (№ 29 и № 30) эксперты ФИПИ строго различают две записи:\n- **Степень окисления** — сначала **знак**, потом цифра: Mn^{+7}, Fe^{+3}, S^{−2}, а в пероксидах −1.\n- **Заряд иона** — сначала **цифра**, потом знак: Mn^{2+}, Fe^{3+}, SO4^{2−}, Cr2O7^{2−}.\n- **Электрон** обозначается как e⁻ (или e^{−}).\nЗа путаницу этих форматов в электронном балансе или ионном уравнении снимают балл."}, "01.13": {"t": "Модуль 01 · 3. Окислитель, восстановитель и шкала степеней окисления", "x": "• **Максимальная СО** (обычно равна номеру группы, кроме F, O, Fe и др.) — атому больше нечего отдавать, значит этот элемент может быть **только окислителем** (Mn^{+7} в KMnO4, Cr^{+6} в K2Cr2O7, S^{+6} в H2SO4, N^{+5} в HNO3, Fe^{+3} в типичных ОВР ЕГЭ — о редком окислении до феррата Fe^{+6} смотри модуль 06).\n• **Минимальная СО** (для металлов 0, для неметаллов N_{группы} − 8) — атому некуда принимать электроны, значит элемент может быть **только восстановителем** (Na^{0}, Fe^{0}, I^{−1} в KI, S^{−2} в H2S, N^{−3} в NH3).\n• **Промежуточная СО** — атом может и отдавать, и принимать электроны, поэтому проявляет **двойственные свойства** (и окислитель, и восстановитель): S^{0}, S^{+4} (SO2, Na2SO3), N^{+3} (KNO2), O^{−1} (H2O2), Fe^{+2} (FeSO4), Cl2^{0}."}, "02": {"t": "Модуль 02. Все форматы и ловушки задания № 19 КИМ", "x": "В задании № 19 проверяют 4 формулировки: роль элемента (или вещества), формулу окислителя/восстановителя, переход СО и число отданных/принятых электронов. Главная защита от ошибки — точно различать **конкретный элемент** и **вещество целиком**."}, "02.1": {"t": "Модуль 02 · Главная мысль.", "x": "В задании № 19 проверяют 4 формулировки: роль элемента (или вещества), формулу окислителя/восстановителя, переход СО и число отданных/принятых электронов. Главная защита от ошибки — точно различать **конкретный элемент** и **вещество целиком**."}, "02.3": {"t": "Модуль 02 · 1. Четыре реальные формулировки задания № 19", "x": "• **«Установите соответствие между уравнением и свойством, которое проявляет элемент X»** — Что именно ищем: 1) только окислитель; 2) только восстановитель; 3) и окислитель, и восстановитель; 4) не проявляет ОВ-свойств; На чём чаще всего ловят: Свойство **элемента** смотрят по конкретной реакции, а не вообще! Например, в Cu + 4HNO3(конц.) → Cu(NO3)2 + 2NO2↑ + 2H2O азот — только окислитель (часть не меняет СО, но роль в ОВР — окислитель).\n• **«Установите соответствие между схемой реакции и формулой вещества-восстановителя (или окислителя)»** — Что именно ищем: Полная формула **исходного реагента**, в котором есть атом-донор (или акцептор) e⁻; На чём чаще всего ловят: Выбор продукта справа или выбор кислоты-среды (H2SO4(разб.)), которая СО не меняет.…"}, "02.6": {"t": "Модуль 02 · 2. Элемент vs вещество: 4 главных «хамелеона» № 19", "x": "• ****Вода (H2O)**** — Как окислитель: За счёт H^{+1} с активными металлами, Fe/C при t°: 2Na + 2H2O → 2NaOH + H2↑; Как восстановитель: За счёт O^{−2} со фтором: 2F2 + 2H2O → 4HF + O2↑; Не-ОВР / среда / диспропорционирование: В KMnO4 + Na2SO3 + H2O — просто среда (СО H и O не меняются)\n• ****Пероксид (H2O2)**** — Как окислитель: O^{−1} → O^{−2} с KI, FeSO4, Na2SO3: 2KI + H2O2 + H2SO4(разб.) → I2↓ + K2SO4 + 2H2O; Как восстановитель: O^{−1} → O2^{0} с KMnO4, K2Cr2O7, Cl2: 2KMnO4 + 5H2O2 + 3H2SO4(разб.) → 2MnSO4 + 5O2↑ + K2SO4 + 8H2O; Не-ОВР / среда / диспропорционирование: Диспропорционирование: 2H2O2 —MnO2→ 2H2O + O2↑ (O^{−1} и окислитель, и восстановитель)…"}, "02.9": {"t": "Модуль 02 · 3. Органические реакции и не-ОВР двойники в № 19", "x": "• **Окисление альдегидов и муравьиной кислоты (HCOOH):** CH3CHO + 2[Ag(NH3)2]OH —t°→ CH3COONH4 + 2Ag↓ + 3NH3↑ + H2O — карбонильный углерод повышает СО с +1 до +3 (восстановитель), серебро Ag^{+1} → Ag^{0} (окислитель). Муравьиная кислота HCOOH имеет альдегидную группу и окисляется до CO2 (C^{+2} → C^{+4}).\n• **Гидрирование алкенов/алкинов/альдегидов:** CH2=CH2 + H2 —t°, Ni→ CH3–CH3 — углерод понижает СО с −2 до −3 (органическое вещество здесь **окислитель**, а H2 — **восстановитель**!).\n• **Реакции НЕ-ОВР (часто прячут в вариантах № 19):** реакции ионного обмена (BaCl2 + Na2SO4), гидролиз солей и сложных эфиров, дегидратация спиртов, гидратация алкенов (C2H4 + H2O), термическое разложение CaCO3 или Cu(OH)2, а также переходы 2K2CrO4 + H2SO4 → K2Cr2O7 + K2SO4 + H2O (у хрома и слева, и справа +6!)."}, "02.10": {"t": "Модуль 02 · Ловушка № 19: двойное окисление — не диспропорционирование", "x": "В реакции FeS2 + O2 (обжиг пирита) **два** элемента в одном веществе отдают электроны: Fe^{+2} → Fe^{+3} и S^{−1} → S^{+4}. Значит, и железо, и сера — восстановители, а кислород O2^{0} → O^{−2} — единственный окислитель. Не перепутай это с диспропорционированием: здесь окисляются два разных элемента, а восстанавливается третий."}, "02.12": {"t": "Модуль 02 · 4. Пошаговый разбор прототипа задания № 19", "x": "**Шаг 1.** **Условие прототипа:** установите соответствие между уравнением реакции и свойством, которое проявляет **азот** в этой реакции:\nА) NH4NO3 —t°→ N2O↑ + 2H2O\nБ) 2NO2 + 2NaOH → NaNO2 + NaNO3 + H2O\nВ) NH4Cl + NaOH —t°→ NaCl + NH3↑ + H2O\nВарианты: 1) только окислитель; 2) только восстановитель; 3) и окислитель, и восстановитель; 4) не проявляет ОВ-свойств.\n**Шаг 2.** **Анализируем А (NH4NO3 → N2O + 2H2O):** в NH4^{+} азот N^{−3}, в NO3^{−} азот N^{+5}, в продукте N2O азот N^{+1}. Один атом азота повысил СО (−3 → +1), другой понизил (+5 → +1). Значит, элемент азот — **и окислитель, и восстановитель (3)** (внутримолекулярное сопропорционирование).\n**Шаг 3.** **Анализируем Б (2NO2 + 2NaOH → NaNO2 + NaNO3 + H2O):** в NO2 азот N^{+4}, в NaNO2 — N^{+3} (понизил), в NaNO3 — N^{+5} (повысил). Это классическое диспропорционирование: азот — **и окислитель, и восстановитель (3)**.…"}, "03": {"t": "Модуль 03. Метод электронного баланса и критерии 2/2 в № 29", "x": "Главный закон электронного баланса: **сколько электронов отдал восстановитель, ровно столько же принял окислитель**. Наименьшее общее кратное (НОК) этих чисел сразу даёт коэффициенты перед продуктами и реагентами ОВР."}, "03.1": {"t": "Модуль 03 · Главная мысль.", "x": "Главный закон электронного баланса: **сколько электронов отдал восстановитель, ровно столько же принял окислитель**. Наименьшее общее кратное (НОК) этих чисел сразу даёт коэффициенты перед продуктами и реагентами ОВР."}, "03.4": {"t": "Модуль 03 · 1. Как работает электронный баланс (алгоритм из 5 шагов)", "x": "**Шаг 1. Расставь СО** и выпиши только те элементы, у которых СО изменилась. В реакции KMnO4 с HCl(конц.) (продукты: KCl, MnCl2, Cl2↑, H2O) меняются степени окисления Mn^{+7} → Mn^{+2} и Cl^{−1} → Cl2^{0}.\n**Шаг 2. Учти индексы двухатомных молекул (правило удвоения).** В продукте Cl2 два атома хлора. Если записать 2Cl^{−1} − 2e⁻ → Cl2^{0}, множитель сразу встанет перед Cl2, и не придётся возиться с дробями.\n**Шаг 3. Найди НОК и дополнительные множители.** Mn^{+7} + 5e⁻ → Mn^{+2} (множитель 2), 2Cl^{−1} − 2e⁻ → Cl2^{0} (множитель 5). Отдано 10e⁻, принято 10e⁻.\n**Шаг 4. Перенеси коэффициенты и уравняй среду.** Ставим 2 перед KMnO4, 2 перед MnCl2, 5 перед Cl2. Далее уравниваем металлы (2KCl), затем хлор-среду: справа 2 + 4 + 10 = 16 атомов хлора → ставим 16 перед HCl(конц.). Значит, воды 8H2O.\n**Шаг 5. Обязательная проверка по кислороду.** Слева в 2KMnO4: 2·4 = 8 атомов O. Справа в 8H2O: 8·1 = 8 атомов O. Баланс сошёлся на 100%!"}, "03.5": {"t": "Модуль 03 · 1. Как работает электронный баланс (алгоритм из 5 шагов)", "x": "2KMnO4 + 16HCl(конц.) → 2KCl + 2MnCl2 + 5Cl2↑ + 8H2O"}, "03.8": {"t": "Модуль 03 · 2. Сложные случаи баланса: двойное окисление и диспропорционирование", "x": "**Пример 1 — двойное окисление (обжиг пирита):** при прокаливании FeS2 в кислороде O2 образуются оксид железа(III) Fe2O3 и сернистый газ SO2↑.\n**Шаг 2.** **Складываем отдачи в одной формуле FeS2:** Fe^{+2} − 1e⁻ → Fe^{+3} и 2S^{−1} − 10e⁻ → 2S^{+4}. Итого одна формульная единица FeS2 отдаёт 1 + 10 = 11e⁻.\n**Шаг 3.** **Записываем окислитель с удвоением:** O2^{0} + 4e⁻ → 2O^{−2} (принимает 4e⁻).\n**Шаг 4.** **Находим множители:** НОК(11, 4) = 44 → перед FeS2 ставим 4, перед O2 ставим 11. Отсюда 2Fe2O3 и 8SO2.\n**Шаг 5.** **Проверка по кислороду:** слева 11·2 = 22 атома O; справа 2·3 + 8·2 = 6 + 16 = 22 атома O. Уравнение сошлось!"}, "03.9": {"t": "Модуль 03 · 2. Сложные случаи баланса: двойное окисление и диспропорционирование", "x": "4FeS2 + 11O2 —t°→ 2Fe2O3 + 8SO2↑"}, "03.11": {"t": "Модуль 03 · 2. Сложные случаи баланса: двойное окисление и диспропорционирование", "x": "3Cl2 + 6KOH(гор.) —t°→ 5KCl + KClO3 + 3H2O"}, "03.15": {"t": "Модуль 03 · Золотой стандарт оформления на 2/2 балла", "x": "**Как безопасно оформить окислитель и восстановитель в № 29:**\nПиши **формулу исходного вещества целиком** и уточняй элемент в скобках, например:\nKMnO4 (за счёт Mn^{+7}) — окислитель;\nHCl (за счёт Cl^{−1}) — восстановитель.\nТак ты гарантированно выполнишь требования любого регионального эксперта и не допустишь путаницы между веществом и элементом."}, "04": {"t": "Модуль 04. Среда раствора (pH) и главные окислители: KMnO4 и хром", "x": "Среда раствора (H^{+}, H2O, OH^{−}) определяет, насколько глубоко восстановится окислитель и в какой форме (соль, оксид/гидроксид или анион) окажутся продукты. В кислой среде окислительная способность KMnO4 и K2Cr2O7 максимальна."}, "04.1": {"t": "Модуль 04 · Главная мысль.", "x": "Среда раствора (H^{+}, H2O, OH^{−}) определяет, насколько глубоко восстановится окислитель и в какой форме (соль, оксид/гидроксид или анион) окажутся продукты. В кислой среде окислительная способность KMnO4 и K2Cr2O7 максимальна."}, "04.4": {"t": "Модуль 04 · 1. Как выбрать среду из перечня № 29 и не попасть в капкан", "x": "• **Идеальная кислая среда:** H2SO4(разб.) — сульфат-ион SO4^{2−} в разбавленном растворе инертен. Если в перечне нет H2SO4, её роль отлично выполняют **кислые соли сильной кислоты**: KHSO4, NaHSO4 или NH4HSO4 (именно NH4HSO4 есть в перечне Демоверсии-2027!).\n• **Запрещённые «кислые среды»:** HCl нельзя брать как инертную среду для KMnO4 и K2Cr2O7 — хлорид-ион сам окислится до Cl2↑! HNO3 нельзя брать как инертную среду — она сама сильный окислитель.\n• **Щелочная среда:** KOH, NaOH, Ba(OH)2. Если продукт — кислотный оксид (например, SO2 или CO2), в щёлочи он никогда не выделится газом, а сразу превратится в соль (K2SO3, K2CO3).\n• **Нейтральная среда:** H2O (можно добавлять всегда, даже если воды нет в перечне — в условии сказано «или воду»)."}, "04.8": {"t": "Модуль 04 · 2. Перманганат калия (KMnO4) в трёх средах", "x": "2KMnO4 + 5Na2SO3 + 3H2SO4(разб.) → 2MnSO4 + 5Na2SO4 + K2SO4 + 3H2O\n2KMnO4 + 5K2SO3 + 6KHSO4 → 2MnSO4 + 9K2SO4 + 3H2O\n2KMnO4 + 3Na2SO3 + H2O → 2MnO2↓ + 3Na2SO4 + 2KOH\n2KMnO4 + Na2SO3 + 2KOH → 2K2MnO4 + Na2SO4 + H2O"}, "04.11": {"t": "Модуль 04 · 3. Соединения хрома (+6 и +3) в трёх средах", "x": "Хром +6 существует в виде двух анионов, которые переходят друг в друга **без ОВР** при изменении pH: в кислой среде преобладает оранжевый **дихромат** Cr2O7^{2−}, а в щелочной — жёлтый **хромат** CrO4^{2−}:"}, "04.12": {"t": "Модуль 04 · 3. Соединения хрома (+6 и +3) в трёх средах", "x": "K2Cr2O7 + 2KOH → 2K2CrO4 + H2O"}, "04.14": {"t": "Модуль 04 · 3. Соединения хрома (+6 и +3) в трёх средах", "x": "• **Кислая (H2SO4, KHSO4)** — Исходная форма Cr^{+6}: Оранжевый K2Cr2O7 (или K2CrO4); Продукт Cr^{+3}: Соль Cr2(SO4)3 (Cr^{3+}); Визуальный признак: Раствор меняет цвет с оранжевого/жёлтого на зелёный (или фиолетово-зелёный)\n• **Нейтральная (H2O)** — Исходная форма Cr^{+6}: K2Cr2O7 / K2CrO4; Продукт Cr^{+3}: Осадок Cr(OH)3↓; Визуальный признак: Выпадение серо-зелёного осадка\n• **Щелочная (KOH, NaOH)** — Исходная форма Cr^{+6}: Жёлтый K2CrO4 (или K2Cr2O7); Продукт Cr^{+3}: Гидроксокомплекс K[Cr(OH)4] или K3[Cr(OH)6]; Визуальный признак: Прозрачный изумрудно-зелёный раствор без осадка"}, "04.16": {"t": "Модуль 04 · 3. Соединения хрома (+6 и +3) в трёх средах", "x": "2K3[Cr(OH)6] + 3H2O2 → 2K2CrO4 + 2KOH + 8H2O"}, "04.18": {"t": "Модуль 04 · 4. Эталонный разбор задания № 29 из Демоверсии ЕГЭ-2027", "x": "**Шаг 1.** **Условие (Демоверсия ФИПИ ЕГЭ-2027, № 29):** перечень веществ — *нитрит калия (KNO2), сульфит калия (K2SO3), дихромат калия (K2Cr2O7), серная кислота (H2SO4), иодид калия (KI), гидросульфат аммония (NH4HSO4)*. Выберите окислитель и восстановитель, реакция между которыми в соответствующей среде протекает **с образованием простого вещества и раствора двух солей**.\n**Шаг 2.** **Отбор пары:** сильный окислитель — K2Cr2O7 (степень окисления хрома +6). Простое вещество из нашего перечня даст именно KI: иодид-ион I^{−} окисляется до простого вещества I2↓ (бурый осадок / буро-жёлтый раствор)! (KNO2 и K2SO3 дали бы соли KNO3 и K2SO4, а не простое вещество.)\n**Шаг 3.** **Выбор среды:** берём H2SO4(разб.) (тогда в продуктах будут соли только калия и хрома: Cr2(SO4)3 и K2SO4 — ровно **две соли**!). Если бы взяли NH4HSO4, в растворе оказались бы три соли (Cr2(SO4)3, K2SO4, (NH4)2SO4), что нарушает условие «раствора двух солей»!…"}, "04.19": {"t": "Модуль 04 · 4. Эталонный разбор задания № 29 из Демоверсии ЕГЭ-2027", "x": "K2Cr2O7 + 6KI + 7H2SO4(разб.) → 3I2↓ + Cr2(SO4)3 + 4K2SO4 + 7H2O"}, "05": {"t": "Модуль 05. Кислоты-окислители, нитриты, H2O2 и галогены", "x": "HNO3 (любой концентрации) и H2SO4(конц.) окисляют за счёт атомов N^{+5} и S^{+6}, а не H^{+1}, поэтому **водород с металлами они не выделяют** (в ЕГЭ). Продукт восстановления зависит от концентрации кислоты и активности восстановителя."}, "05.1": {"t": "Модуль 05 · Главная мысль.", "x": "HNO3 (любой концентрации) и H2SO4(конц.) окисляют за счёт атомов N^{+5} и S^{+6}, а не H^{+1}, поэтому **водород с металлами они не выделяют** (в ЕГЭ). Продукт восстановления зависит от концентрации кислоты и активности восстановителя."}, "05.3": {"t": "Модуль 05 · 1. Азотная и концентрированная серная кислоты с металлами и неметаллами", "x": "• **Малоактивные металлы (Cu, Ag, Hg)** — HNO3(конц.): NO2↑ (бурый газ); HNO3(разб.): NO↑ (бесцветный газ, буреет на воздухе); H2SO4(конц.): SO2↑ (при нагревании)\n• **Активные металлы (Mg, Zn, Ca)** — HNO3(конц.): NO2↑ или N2O↑; HNO3(разб.): NH4NO3 или N2O↑/N2↑ (в очень разб. — NH4NO3); H2SO4(конц.): H2S↑ (или S↓, с Zn — H2S/S/SO2)\n• **Fe, Al, Cr** — HNO3(конц.): **Пассивация** на холоде; при t° → соль +3 и NO2↑; HNO3(разб.): Реагируют без t° → соль +3 и NO↑ (или N2O/NH4NO3); H2SO4(конц.): **Пассивация** на холоде; при t° → соль +3 и SO2↑\n• **Неметаллы (C, S, P)** — HNO3(конц.): CO2, H2SO4, H3PO4 + NO2↑; HNO3(разб.): H3PO4 + NO↑ (для P при t°); H2SO4(конц.): CO2 + SO2↑ (C), SO2↑ (S), H3PO4 + SO2↑ (P при t°)"}, "05.4": {"t": "Модуль 05 · 1. Азотная и концентрированная серная кислоты с металлами и неметаллами", "x": "Cu + 4HNO3(конц.) → Cu(NO3)2 + 2NO2↑ + 2H2O\n3Cu + 8HNO3(разб.) → 3Cu(NO3)2 + 2NO↑ + 4H2O\nCu + 2H2SO4(конц.) —t°→ CuSO4 + SO2↑ + 2H2O\nCu2S + 12HNO3(конц.) → Cu(NO3)2 + CuSO4 + 10NO2↑ + 6H2O"}, "05.6": {"t": "Модуль 05 · Ловушки на 95–100 баллов", "x": "**Классические ловушки кислот-окислителей:**\n1. Fe, Al, Cr на холоде **пассивируются** HNO3(конц.) и H2SO4(конц.), а при нагревании дают соли в СО **+3** (Fe(NO3)3, Fe2(SO4)3), а не +2! То же касается FeO и Fe(OH)2 с HNO3 или H2SO4(конц.): они окисляются до Fe^{+3}.\n2. H2SO4(конц.) с твёрдыми галогенидами: с NaCl идёт **не-ОВР** (NaCl(тв.) + H2SO4(конц.) —t°→ NaHSO4 + HCl↑), с NaBr идёт ОВР до **Br2 + SO2↑**, а с NaI (сильнейший восстановитель!) — до **I2 + H2S↑**.\n3. Нитраты в **щелочной среде** окисляют Zn и Al до гидроксокомплексов, восстанавливаясь до **аммиака NH3↑**:"}, "05.7": {"t": "Модуль 05 · 1. Азотная и концентрированная серная кислоты с металлами и неметаллами", "x": "4Zn + NaNO3 + 7NaOH + 6H2O —t°→ 4Na2[Zn(OH)4] + NH3↑"}, "05.10": {"t": "Модуль 05 · 2. Нитриты (KNO2) и пероксид водорода (H2O2) — мастера двойственности", "x": "**Шаг 1.** **KNO2 как восстановитель (N^{+3} → N^{+5}):** с сильными окислителями (KMnO4, K2Cr2O7, Cl2, H2O2) переходит в нитрат KNO3:\n2KMnO4 + 5KNO2 + 3H2SO4(разб.) → 2MnSO4 + 5KNO3 + K2SO4 + 3H2O (обесцвечивание раствора без газа и осадка!).\n**Шаг 2.** **KNO2 как окислитель (N^{+3} → N^{+2}, газ NO↑):** в кислой среде с сильными восстановителями (KI, H2S, FeSO4) восстанавливается до бесцветного газа NO↑:\n2KNO2 + 2KI + 2H2SO4(разб.) → I2↓ + 2NO↑ + 2K2SO4 + 2H2O.\n**Шаг 3.** **H2O2 как окислитель (O^{−1} → O^{−2} в H2O/OH^{−}):** с KI, FeSO4, Na2SO3, Cr(OH)3/K3[Cr(OH)6] — газ не выделяется!\n2KI + H2O2 + H2SO4(разб.) → I2↓ + K2SO4 + 2H2O.\n**Шаг 4.** **H2O2 как восстановитель (O^{−1} → O2^{0}↑):** с KMnO4, K2Cr2O7, Cl2, Ag2O — всегда выделяется **газ O2↑**!\n2KMnO4 + 5H2O2 + 3H2SO4(разб.) → 2MnSO4 + 5O2↑ + K2SO4 + 8H2O."}, "05.13": {"t": "Модуль 05 · 3. Галогены, их ряд активности и оксогалогениды", "x": "Cl2 + 2KBr → 2KCl + Br2\nBr2 + 2KI → 2KBr + I2↓"}, "05.17": {"t": "Модуль 05 · 3. Галогены, их ряд активности и оксогалогениды", "x": "KClO3 + 6HCl(конц.) → KCl + 3Cl2↑ + 3H2O\nKClO3 + 6KI + 3H2SO4(разб.) → KCl + 3I2↓ + 3K2SO4 + 3H2O\nKIO3 + 5KI + 3H2SO4(разб.) → 3I2↓ + 3K2SO4 + 3H2O"}, "06": {"t": "Модуль 06. Восстановители, признаки реакций и алгоритм отбора пары № 29", "x": "Чтобы взять 2/2 балла в № 29, нужно не просто знать пары «окислитель + восстановитель», а уметь **фильтровать** их по качественному признаку из условия и не спутать ОВР с реакцией ионного обмена из № 30."}, "06.1": {"t": "Модуль 06 · Главная мысль.", "x": "Чтобы взять 2/2 балла в № 29, нужно не просто знать пары «окислитель + восстановитель», а уметь **фильтровать** их по качественному признаку из условия и не спутать ОВР с реакцией ионного обмена из № 30."}, "06.6": {"t": "Модуль 06 · 2. Особые пары ОВР и граница с РИО (№ 30)", "x": "2FeCl3 + 2KI → 2FeCl2 + I2↓ + 2KCl\n2CuSO4 + 4KI → 2CuI↓ + I2↓ + 2K2SO4\n2FeCl3 + H2S → 2FeCl2 + S↓ + 2HCl\n2FeCl3 + Na2SO3 + H2O → 2FeCl2 + Na2SO4 + 2HCl"}, "06.7": {"t": "Модуль 06 · Граница между № 29 и № 30 и правило совместимости", "x": "**Граница между № 29 и № 30 + правило совместимости продуктов:**\n- Al^{3+} и Cr^{3+} с CO3^{2−}, S^{2−}, SO3^{2−}, а также Fe^{3+} с CO3^{2−}/HCO3^{−} — это **не-ОВР** (совместный гидролиз для № 30). А Fe^{3+} + I^{−}/S^{2−}/SO3^{2−} и Cu^{2+} + I^{−} — это **ОВР** (для № 29).\n- **Правило перечня и совместимости:** нельзя добавлять реагенты не из перечня (кроме H2O, если она разрешена условием), и нельзя записывать в правой части несовместимые продукты (например, кислоту и щёлочь, NH3 и HCl, карбонат или гидроксид в кислой среде)."}, "06.9": {"t": "Модуль 06 · 3. Словарь качественных признаков в условии № 29", "x": "• **«Обесцвечивание раствора, без осадка и газа»** — Что должно получиться: Фиолетовый KMnO4 переходит в бесцветный Mn^{2+}, восстановитель не даёт ни газа, ни осадка; Типичный пример пары: KMnO4 + Na2SO3 + H2SO4(разб.) или KMnO4 + KNO2 + H2SO4(разб.)\n• **«Выделение газа и выпадение осадка»** — Что должно получиться: Один продукт — газ, второй — нерастворимое вещество; Типичный пример пары: 2KNO2 + 2KI + 2H2SO4(разб.) → I2↓ + 2NO↑ + 2K2SO4 + 2H2O\n• **«Образование простого вещества и раствора двух солей»** — Что должно получиться: I2↓, S↓, Br2, Cl2↑, O2↑, N2↑ + ровно 2 соли в растворе; Типичный пример пары: K2Cr2O7 + 6KI + 7H2SO4(разб.) → 3I2↓ + Cr2(SO4)3 + 4K2SO4 + 7H2O\n• **«Выпадение бурого осадка»** — Что должно получиться: MnO2↓ (нейтральная среда для KMnO4) или Fe(OH)3↓; Типичный пример пары: 2KMnO4 + 3K2SO3 + H2O → 2MnO2↓ + 3K2SO4 + 2KOH…"}, "06.11": {"t": "Модуль 06 · 4. Пятишаговый алгоритм отбора пары № 29 (разбор вслух)", "x": "**Шаг 1.** **Условие прототипа:** даны *перманганат калия (KMnO4), сульфит натрия (Na2SO3), иодид калия (KI), серная кислота (H2SO4), гидроксид бария (Ba(OH)2), сульфат железа(II) (FeSO4)*. Выберите вещества, реакция между которыми приводит к **обесцвечиванию раствора без образования осадка и выделения газа**.\n**Шаг 1. Распредели 6 веществ по ролям:** окислитель — KMnO4; восстановители — Na2SO3, KI, FeSO4; среды — H2SO4(разб.) (кислая), Ba(OH)2 (щелочная), плюс H2O.\n**Шаг 2. Отсей по признаку «обесцвечивание раствора»:** обесцвечивание фиолетового KMnO4 происходит только в **кислой среде** (Mn^{+7} → Mn^{+2}). Значит, берём среду H2SO4(разб.).\n**Шаг 3. Отсей лишние восстановители по запрету осадка и газа:** KI даст бурый осадок I2↓ — отбрасываем! FeSO4 даст жёлто-бурый раствор Fe2(SO4)3 (раствор не обесцветится, а станет жёлтым!) — отбрасываем! Остаётся Na2SO3: SO3^{2−} → SO4^{2−} (бесцветный раствор, без газа и осадка).…"}, "07": {"t": "Модуль 07. Физика электролиза и электролиз расплавов", "x": "[[Электролиз]] — это вынужденная окислительно-восстановительная реакция, которая идёт на электродах при пропускании **постоянного** электрического тока через расплав или раствор электролита. На **катоде (–)** всегда идёт **восстановление**, на **аноде (+)** — **окисление**."}, "07.1": {"t": "Модуль 07 · Главная мысль.", "x": "[[Электролиз]] — это вынужденная окислительно-восстановительная реакция, которая идёт на электродах при пропускании **постоянного** электрического тока через расплав или раствор электролита. На **катоде (–)** всегда идёт **восстановление**, на **аноде (+)** — **окисление**."}, "07.10": {"t": "Модуль 07 · 2. Электролиз расплавов: когда воды нет, конкуренции нет", "x": "**Шаг 1.** **Расплав хлорида натрия (NaCl):**\nКатод (–): Na^{+} + e⁻ → Na (×2)\nАнод (+): 2Cl^{−} − 2e⁻ → Cl2↑ (×1)\nСуммарно: 2NaCl(расплав) —электролиз→ 2Na + Cl2↑.\n**Шаг 2.** **Расплав фторида калия (KF):** единственный способ получить фтор F2!\nКатод (–): K^{+} + e⁻ → K (×2)\nАнод (+): 2F^{−} − 2e⁻ → F2↑ (×1)\nСуммарно: 2KF(расплав) —электролиз→ 2K + F2↑.\n**Шаг 3.** **Расплав щёлочи (NaOH):** на катоде металл, на аноде окисляются OH^{−} до кислорода и воды:\nКатод (–): Na^{+} + e⁻ → Na (×4)\nАнод (+): 4OH^{−} − 4e⁻ → O2↑ + 2H2O↑ (×1)\nСуммарно: 4NaOH(расплав) —электролиз→ 4Na + O2↑ + 2H2O↑.\n**Шаг 4.** **Расплав гидрида (NaH):** здесь водород имеет СО −1 (H^{−}), поэтому идёт к **аноду (+)**!\nКатод (–): Na^{+} + e⁻ → Na (×2)\nАнод (+): 2H^{−} − 2e⁻ → H2↑ (×1)\nСуммарно: 2NaH(расплав) —электролиз→ 2Na + H2↑.\n**Шаг 5.** **Получение алюминия (Al2O3 в расплаве [[Криолит|криолита]] Na3AlF6):**\nКатод (–): Al^{3+} + 3e⁻ → Al (×4)…"}, "07.11": {"t": "Модуль 07 · 2. Электролиз расплавов: когда воды нет, конкуренции нет", "x": "2NaCl(расплав) —электролиз→ 2Na + Cl2↑\n2KF(расплав) —электролиз→ 2K + F2↑\n4NaOH(расплав) —электролиз→ 4Na + O2↑ + 2H2O↑\n2Al2O3(расплав в Na3AlF6) —электролиз→ 4Al + 3O2↑"}, "07.12": {"t": "Модуль 07 · Ловушка ЕГЭ: AlCl3 vs Al2O3 в криолите", "x": "**Две частые ловушки по расплавам в № 20:**\n1. **Почему алюминий получают из Al2O3 в криолите, а не из расплава AlCl3?** Безводный AlCl3 имеет ковалентную полярную связь и молекулярную решётку: при нагревании (~180 °C) он возгоняется, а его расплав практически не содержит ионов и **не проводит электрический ток**. А чистый Al2O3 плавится выше 2050 °C — добавка криолита Na3AlF6 снижает температуру электролиза примерно до 950 °C.\n2. **Кислородсодержащие соли (KNO3, Na2CO3, Na2SO4)** в расплаве при нагревании часто термически разлагаются ещё до электролиза или дают сложные продукты — в № 20 ЕГЭ для расплавов обычно спрашивают галогениды (NaCl, KCl, CaCl2, MgCl2, KF), щёлочи (NaOH, KOH) и Al2O3 в криолите."}, "07.13": {"t": "Модуль 07 · Мост к КИМ (№ 20 КИМ (базовый, 1 балл))", "x": "**Как спрашивают:** Установить продукты электролиза расплава соли/щёлочи или выбрать способ получения активного металла (Na, K, Ca, Mg, Al) либо фтора (F2).\n**На чём ловят:** Всегда ищи в условии слово **«расплав»** или **«водный раствор»** — от одного этого слова ответ меняется на противоположный!\n**Как читать:** Если вещество в расплаве — мысленно вычеркни воду и разряжай прямо катион на катоде и анион на аноде."}, "08": {"t": "Модуль 08. Электролиз водных растворов: правила катода и анода", "x": "В водном растворе на обоих электродах с ионами соли конкурируют молекулы воды (H2O). Кто легче принимает электроны — тот побеждает на **катоде**; кто легче отдаёт электроны — тот побеждает на **аноде**."}, "08.1": {"t": "Модуль 08 · Главная мысль.", "x": "В водном растворе на обоих электродах с ионами соли конкурируют молекулы воды (H2O). Кто легче принимает электроны — тот побеждает на **катоде**; кто легче отдаёт электроны — тот побеждает на **аноде**."}, "08.8": {"t": "Модуль 08 · 2. Правило катода (–): три зоны ряда напряжений", "x": "• **Li^{+} … Al^{3+} (до Al включительно) и NH4^{+}** — Продукт на инертном катоде (–): **Только водород (H2)**; Уравнение катодного процесса: 2H2O + 2e⁻ → H2↑ + 2OH^{−}\n• **Mn^{2+} … Pb^{2+} (Mn, Zn, Cr, Fe, Cd, Co, Ni, Sn, Pb)** — Продукт на инертном катоде (–): **Металл (Me) и водород (H2)**; Уравнение катодного процесса: Me^{n+} + n e⁻ → Me и 2H2O + 2e⁻ → H2↑ + 2OH^{−}\n• **Cu^{2+} … Au^{3+} (Cu, Hg, Ag, Pt, Au)** — Продукт на инертном катоде (–): **Только металл (Me)**; Уравнение катодного процесса: Me^{n+} + n e⁻ → Me\n• **H^{+} (водные растворы кислот)** — Продукт на инертном катоде (–): **Водород (H2)**; Уравнение катодного процесса: 2H^{+} + 2e⁻ → H2↑"}, "08.12": {"t": "Модуль 08 · Ловушки на 100 баллов: F⁻, средняя активность и NH4⁺", "x": "**Четыре главные ловушки водных растворов в № 20:**\n1. **Фториды (NaF, KF, CuF2, HF):** на аноде в водном растворе **всегда O2↑**, а НЕ фтор! Фтор F2 получают только из расплава.\n2. **Металлы средней активности (Fe, Zn, Cr, Ni, Sn, Pb):** в № 20 на катоде выбирай вариант **«металл и водород»**, а не «только металл»! (Даже для FeCl3: Fe^{3+} восстанавливается ступенчато до Fe^{2+} и далее параллельно Fe и H2, в рамках № 20 ответ — металл и водород.)\n3. **Соли аммония (NH4Cl, (NH4)2SO4):** ион NH4^{+} в № 20 ведёт себя как активный металл — главный продукт на катоде **водород (H2)**.\n4. **Кислые соли активных металлов и оксокислот (KHSO4, NaHCO3, NaH2PO4):** на катоде выделяется H2, на аноде — O2 (фактически электролиз воды)."}, "08.14": {"t": "Модуль 08 · 4. Пошаговый разбор пяти солей в водном растворе", "x": "**Шаг 1.** **NaF (водн. р-р):** Na^{+} стоит до Al → катод **H2**. F^{−} — исключение среди бескислородных → анод **O2**.\n**Шаг 2.** **CuCl2 (водн. р-р):** Cu^{2+} стоит после H2 → катод **Cu**. Cl^{−} — бескислородный (не F^{−}) → анод **Cl2**.\n**Шаг 3.** **Fe(NO3)2 (водн. р-р):** Fe^{2+} стоит между Al и H2 → катод **Fe и H2**. NO3^{−} — кислородсодержащий → анод **O2**.\n**Шаг 4.** **AgNO3 (водн. р-р):** Ag^{+} стоит после H2 → катод **Ag**. NO3^{−} — кислородсодержащий → анод **O2**.\n**Шаг 5.** **CH3COOK (водн. р-р):** K^{+} стоит до Al → катод **H2**. CH3COO^{−} — карбоксилат (синтез Кольбе) → анод **C2H6 и CO2**."}, "09": {"t": "Модуль 09. Суммарные уравнения электролиза, среда и тонкости на 100 баллов", "x": "Чтобы составить полное уравнение электролиза раствора, сложи катодную и анодную полуреакции (уравняв электроны) и допиши оставшиеся в растворе «ионы-наблюдатели». У катода при разложении воды образуются OH^{−} (щелочная среда), у анода — H^{+} (кислая среда)."}, "09.1": {"t": "Модуль 09 · Главная мысль.", "x": "Чтобы составить полное уравнение электролиза раствора, сложи катодную и анодную полуреакции (уравняв электроны) и допиши оставшиеся в растворе «ионы-наблюдатели». У катода при разложении воды образуются OH^{−} (щелочная среда), у анода — H^{+} (кислая среда)."}, "09.4": {"t": "Модуль 09 · 1. Четыре базовых типа суммарных уравнений электролиза растворов", "x": "• ****1. Активный металл + бескислородный анион** (KCl, NaBr)** — Катод (–) / Анод (+): H2↑ (+ OH^{−}) / Cl2↑; Что остаётся в растворе: Щёлочь KOH (pH растёт!); Суммарное уравнение электролиза: 2KCl + 2H2O —электролиз→ H2↑ + Cl2↑ + 2KOH\n• ****2. Неактивный металл + оксоанион** (CuSO4, AgNO3)** — Катод (–) / Анод (+): Cu / O2↑ (+ H^{+}); Что остаётся в растворе: Кислота H2SO4 (pH падает!); Суммарное уравнение электролиза: 2CuSO4 + 2H2O —электролиз→ 2Cu + O2↑ + 2H2SO4\n• ****3. Неактивный металл + бескислородный анион** (CuCl2)** — Катод (–) / Анод (+): Cu / Cl2↑; Что остаётся в растворе: Вода не участвует, соль просто расходуется; Суммарное уравнение электролиза: CuCl2(р-р) —электролиз→ Cu + Cl2↑…"}, "09.5": {"t": "Модуль 09 · Почему в растворах Na2SO4, H2SO4 и NaOH разлагается только вода?", "x": "Тот же четвёртый результат — **фактический электролиз воды** (2H2O —электролиз→ 2H2↑ + O2↑) — дают водные растворы **щелочей** (NaOH, KOH) и **кислородсодержащих кислот** (H2SO4, HNO3, H3PO4) + HF. Соль, кислота или щёлочь в этом случае служат только переносчиками тока (электролитом), их масса в растворе не меняется, а массовая доля растёт за счёт убыли воды!"}, "09.8": {"t": "Модуль 09 · 2. Особые уравнения: синтез Кольбе, металлы средней активности и HCl", "x": "2CH3COONa + 2H2O —электролиз→ C2H6↑ + 2CO2↑ + H2↑ + 2NaOH\n2CuSO4 + 2H2O —электролиз→ 2Cu + O2↑ + 2H2SO4\n2KCl + 2H2O —электролиз→ H2↑ + Cl2↑ + 2KOH"}, "09.10": {"t": "Модуль 09 · 3. Последовательный электролиз (мост к задаче № 34)", "x": "Что происходит, если электролиз раствора CuSO4 или NaCl не остановить в момент, когда вся соль израсходовалась? Ток продолжает идти — и начинается **второй этап**: электролиз оставшейся воды!"}, "09.14": {"t": "Модуль 09 · 4. Активный (растворимый) анод — граница правила инертных электродов", "x": "Cu − 2e⁻ → Cu^{2+}"}, "10": {"t": "Модуль 10. Все форматы задания № 20 КИМ и промышленные способы получения", "x": "В задании № 20 встречаются **три типа таблиц соответствия**: 1) вещество → продукт на катоде (или аноде); 2) вещество → продукты на обоих электродах; 3) вещество (металл/неметалл) → промышленный способ его получения электролизом."}, "10.1": {"t": "Модуль 10 · Главная мысль.", "x": "В задании № 20 встречаются **три типа таблиц соответствия**: 1) вещество → продукт на катоде (или аноде); 2) вещество → продукты на обоих электродах; 3) вещество (металл/неметалл) → промышленный способ его получения электролизом."}, "10.5": {"t": "Модуль 10 · 1. Промышленные способы получения веществ электролизом", "x": "• **Na, K, Li, Ca, Mg** — Правильный способ электролиза в № 20: Электролиз **расплава** хлорида (NaCl, KCl, CaCl2, MgCl2) или NaOH(расплав); Почему не подходит альтернатива: В водном растворе на катоде выделится H2, а не металл\n• **Al** — Правильный способ электролиза в № 20: Электролиз **раствора Al2O3 в расплаве криолита (Na3AlF6)**; Почему не подходит альтернатива: Водный раствор даёт H2; расплав AlCl3 не проводит ток\n• **F2** — Правильный способ электролиза в № 20: Электролиз **расплава** фторида (KF, NaF / KHF2); Почему не подходит альтернатива: В водном растворе на аноде выделится O2, а не F2\n• **Cl2, H2, NaOH/KOH** — Правильный способ электролиза в № 20: Электролиз **водного раствора** NaCl (или KCl); Почему не подходит альтернатива: Из расплава NaCl получатся Na и Cl2 (без H2 и NaOH!)…"}, "10.7": {"t": "Модуль 10 · 2. Восемь главных ловушек задания № 20", "x": "• **Ловушка 1 — не замечено слово «расплав»:** для NaCl(расплав) на катоде Na, для NaCl(р-р) на катоде H2.\n• **Ловушка 2 — фторид в растворе:** NaF(р-р), CuF2(р-р), AgF(р-р) на аноде всегда дают **O2**, никогда не F2.\n• **Ловушка 3 — металлы средней активности (Mn–Pb):** для ZnSO4, FeCl2, FeCl3, Cr2(SO4)3, Ni(NO3)2, SnCl2, Pb(NO3)2 на катоде всегда **«металл и водород»**, не «только металл».\n• **Ловушка 4 — ртуть (Hg) и медь (Cu) vs свинец (Pb):** Pb стоит **до (H2)** (даёт Pb и H2), а Cu, Hg, Ag стоят **после (H2)** (дают только металл). Всегда сверяйся с рядом на бланке!\n• **Ловушка 5 — соли аммония (NH4Cl, NH4NO3):** на катоде выделяется **H2** (как у активных металлов).\n• **Ловушка 6 — органические соли (CH3COONa, C2H5COOK):** на аноде образуются **алкан (C2H6, C4H10) и CO2**, а не кислород!\n• **Ловушка 7 — перепутаны катод и анод:** катод (–) = **катионы** (металл / H2), анод (+) = **анионы** (галоген / S / O2 / R–R + CO2).…"}, "10.9": {"t": "Модуль 10 · 3. Пошаговый разбор двух реальных прототипов задания № 20", "x": "**Шаг 1.** **Прототип 1 (продукты на инертных электродах):** установите соответствие между формулой соли и продуктами электролиза её **водного раствора** на инертных электродах:\nА) AgNO3 · Б) NaF · В) ZnCl2\nВарианты: 1) металл и кислород; 2) водород и кислород; 3) водород и фтор; 4) металл, водород и хлор; 5) металл и хлор.\n- **А (AgNO3):** Ag^{+} после H2 → только Ag; NO3^{−} оксоанион → O2 → **1 (металл и кислород)**.\n- **Б (NaF):** Na^{+} до Al → H2; F^{−} в растворе не окисляется → O2 → **2 (водород и кислород)** (ловушка — вариант 3!).\n- **В (ZnCl2):** Zn^{2+} между Al и H2 → Zn и H2; Cl^{−} бескислородный → Cl2 → **4 (металл, водород и хлор)** (ловушка — вариант 5!).\n**Ответ:** 124.\n**Шаг 2.** **Прототип 2 (промышленное получение веществ):** установите соответствие между веществом и способом его получения электролизом:\nА) калий · Б) алюминий · В) фтор…"}}, "_kt": "ОВР, электронный баланс (№19, 29) и электролиз (№20) ЕГЭ-2027 с нуля до 100 баллов", "_mods": {"01": "Степень окисления, окислитель и восстановитель", "02": "Все форматы и ловушки задания № 19 КИМ", "03": "Метод электронного баланса и критерии 2/2 в № 29", "04": "Среда раствора (pH) и главные окислители: KMnO4 и хром", "05": "Кислоты-окислители, нитриты, H2O2 и галогены", "06": "Восстановители, признаки реакций и алгоритм отбора пары № 29", "07": "Физика электролиза и электролиз расплавов", "08": "Электролиз водных растворов: правила катода и анода", "09": "Суммарные уравнения электролиза, среда и тонкости на 100 баллов", "10": "Все форматы задания № 20 КИМ и промышленные способы получения"}, "_skm": {"ox_state": ["01"], "kim19_traps": ["02"], "balance_fipi": ["03"], "ph_mn_cr": ["04"], "acids_h2o2_hal": ["05"], "reducers_nav29": ["06"], "melt_electrolysis": ["07"], "solution_rules": ["08"], "summary_electrolysis": ["09"], "kim20_industry": ["10"]}, "_fig": []};
